/* highlights.js — الإضاءات الرسمية («إضاءات نحو تحقيق المؤشر») بلغتين. العربية مصحّحة من ملف الهيئة (2026) (استُخرج النص وصُحّح يدوياً)، والإنجليزية ترجمة مقترحة غير رسمية. تُضاف الدفعات تباعاً. */
window.ETEC_HL_DONE = ["1-1-1-1", "1-1-1-2", "1-2-1-1", "1-2-1-2", "1-2-1-3", "1-2-1-4", "1-2-1-5", "1-3-1-1", "1-3-1-2", "1-3-1-3", "1-4-1-1", "1-4-1-2", "1-4-1-3", "1-4-1-4", "1-4-1-5", "1-4-1-6", "1-4-1-7", "1-5-1-1", "1-5-1-2", "2-1-1-1", "2-1-1-2", "2-1-1-3", "2-1-1-4", "2-1-1-5", "2-1-1-6", "2-1-1-7", "2-1-1-8", "2-1-1-9", "2-2-1-1", "2-2-1-2", "2-2-1-3", "2-2-1-4", "3-1-1-1", "3-1-1-2", "3-1-1-3", "3-1-1-4", "3-1-1-5", "3-1-1-6", "3-2-1-1", "3-2-1-2", "3-2-1-3", "3-2-1-4", "3-2-1-5", "3-2-1-6", "3-2-1-7"];
window.ETEC_HL = {"1-1-1-1": [{"ar": "إعداد خطة تشغيلية شاملة ومكتملة العناصر، بحيث تتضمن: تحليل الواقع، وأهدافاً محددة، وبرامج مزمنة، وأنشطة ومبادرات نوعية، وإجراءات تنفيذ واضحة، مع تحديد الأدوار والمسؤوليات، ومؤشرات أداء لقياس تحقق الأهداف.", "en": "Prepare a comprehensive, fully elaborated operational plan that includes: situation analysis, specific goals, time-bound programs, qualitative activities and initiatives, clear implementation procedures, defined roles and responsibilities, and performance indicators to measure goal achievement."}, {"ar": "مشاركة أكثر من 90% من منسوبي المدرسة في إعداد الخطة التشغيلية.", "en": "More than 90% of school staff take part in preparing the operational plan."}, {"ar": "صياغة الأهداف التفصيلية في الخطة التشغيلية؛ بحيث تكون أهدافاً تطويرية وطموحة، تراعي الإبداع والابتكار، وتكون محددة وواضحة وشاملة وقابلة للتطبيق والقياس، وفق مستويات الأهداف (قريبة المدى/متوسطة المدى/بعيدة المدى).", "en": "Formulate the detailed goals of the operational plan so that they are developmental and ambitious, take creativity and innovation into account, and are specific, clear, comprehensive, applicable and measurable, according to goal levels (short-, medium- and long-term)."}, {"ar": "يتضمن كل هدف: مؤشراً لقياسه، وخطاً أساسياً، ومستهدفاً زمنياً، ومسؤولاً عن التنفيذ، وآلية دورية لقياس التقدم، مع تحديد مستوى الهدف (قريب/متوسط/بعيد) ضمن بطاقة الهدف.", "en": "Each goal includes: an indicator to measure it, a baseline, a time-bound target, a person responsible for implementation, and a periodic mechanism for measuring progress, with the goal level (short/medium/long) stated on the goal card."}, {"ar": "تصميم البرامج والأنشطة في الخطة التشغيلية؛ بحيث تكون مرتبطة بالأهداف التطويرية، ومزمنة، وتغطي جميع المجالات.", "en": "Design the programs and activities in the operational plan so that they are linked to the developmental goals, time-bound, and cover all domains."}, {"ar": "تضمين كل برنامج الهدف التطويري المرتبط به، ومؤشره، وخطوات تنفيذ واضحة.", "en": "Include in each program its related developmental goal, its indicator, and clear implementation steps."}, {"ar": "تحديد الموارد، والجدول الزمني، والفئات المستهدفة، إضافةً إلى مواءمة شاملة لجميع المتعلمين؛ بمن فيهم ذوو الإعاقة، والمتفوقون، والموهوبون؛ لكل برنامج أو نشاط.", "en": "Specify the resources, timeline and target groups, in addition to comprehensive accommodation for all learners, including learners with disabilities, high achievers and gifted learners, for every program or activity."}, {"ar": "تحديد الأدوار وتوزيع المسؤوليات؛ لتنفيذ الخطة التشغيلية على منسوبي المدرسة؛ بحيث تكون متسقة مع الأدوار المعتمدة لمنسوبي المدرسة، وتكون الأدوار مزمنة ومحددة وموزعة على البرامج والأنشطة، وشاملة للمهام والمسؤوليات.", "en": "Define roles and distribute responsibilities for implementing the operational plan among school staff, so that they are consistent with the approved roles of school staff, and the roles are time-bound, specific, distributed across programs and activities, and cover all tasks and responsibilities."}], "1-1-1-2": [{"ar": "إعداد خطة متابعة زمنية للبرامج والأنشطة وتنفيذها.", "en": "Prepare and implement a time-based follow-up plan for the programs and activities."}, {"ar": "تحديد إجراءات متابعة واضحة، وتحديد الأدوار والمسؤوليات.", "en": "Define clear follow-up procedures, roles and responsibilities."}, {"ar": "رصد المشكلات والتحديات أثناء التنفيذ، وتحليل مسبباتها وتصنيفها بحسب الأولوية ودرجة التأثير؛ تمهيداً لمعالجتها.", "en": "Monitor problems and challenges during implementation, analyze their causes and classify them by priority and degree of impact, in preparation for addressing them."}, {"ar": "تقديم الحلول والبدائل لتطوير البرامج والأنشطة، مع تحديد مؤشرات لقياس تقدم التنفيذ.", "en": "Offer solutions and alternatives to develop the programs and activities, and set indicators to measure implementation progress."}, {"ar": "تنفيذ تقويم شامل للخطة والبرامج، مع توفير أدوات متنوعة للتقويم وجمع الأدلة.", "en": "Carry out a comprehensive evaluation of the plan and programs, providing varied evaluation tools and evidence collection."}, {"ar": "مراجعة الخطة وأهدافها، وبرامجها وأنشطتها، ومراجعة المؤشرات لقياس تقدم التنفيذ، ومراجعة الموارد البشرية والمادية والمالية؛ لتحديد نقاط القوة وفرص التحسين، وتقديم الحلول والبدائل لتطوير الأداء.", "en": "Review the plan, its goals, programs and activities, the indicators used to measure implementation progress, and the human, material and financial resources, in order to identify strengths and improvement opportunities and offer solutions and alternatives to develop performance."}, {"ar": "إشراك المجتمع المدرسي في مراجعة الخطة وتطويرها، وتحديد المشكلات والتحديات المتوقعة، واقتراح الحلول والبدائل.", "en": "Involve the school community in reviewing and developing the plan, identifying expected problems and challenges, and proposing solutions and alternatives."}, {"ar": "تطوير الخطة المدرسية استناداً إلى نتائج التقويم؛ عبر تحليل النتائج وتحديد جوانب التطوير، ثم صياغة أهداف تطوير واضحة، وتحديد البرامج والأنشطة المناسبة لها، ووضع إجراءات تطويرية واضحة.", "en": "Develop the school plan based on evaluation results, by analyzing results and identifying areas for development, then formulating clear development goals, identifying suitable programs and activities for them, and setting clear developmental procedures."}], "1-2-1-1": [{"ar": "تنفيذ برامج توعوية للمجتمع المدرسي والمحلي؛ لتعزيز القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة.", "en": "Implement awareness programs for the school and local community to strengthen Islamic values, national identity and loyalty to the wise leadership."}, {"ar": "تضمين القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة في خطة المدرسة وبرامجها وأنشطتها.", "en": "Embed Islamic values, national identity and loyalty to the wise leadership in the school's plan, programs and activities."}, {"ar": "دمج القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة في جميع الممارسات والأنشطة الصفية اليومية.", "en": "Integrate Islamic values, national identity and loyalty to the wise leadership into all daily classroom practices and activities."}, {"ar": "تنفيذ برامج صفية وغير صفية؛ لتعزيز القيم الإسلامية والهوية الوطنية والولاء للقيادة الرشيدة لدى المتعلمين.", "en": "Implement classroom and non-classroom programs to strengthen Islamic values, national identity and loyalty to the wise leadership among learners."}, {"ar": "ترسيخ القيم الإسلامية؛ من خلال ميثاق سلوك يومي (التحية، والأمانة، والمحافظة على الممتلكات)، وإبراز الهوية الوطنية بصرياً (العلم، والشعار، وعبارات قيمية، وصور وقدوات وطنية) في البيئة المدرسية.", "en": "Entrench Islamic values through a daily code of conduct (greeting, honesty, and caring for property), and highlight national identity visually (the flag, the emblem, value-based phrases, and national images and role models) in the school environment."}, {"ar": "الاحتفاء بالمناسبات الوطنية (اليوم الوطني، ويوم التأسيس، ويوم العلم) بشكل منظم يشارك فيه جميع الطلبة.", "en": "Celebrate national occasions (National Day, Founding Day and Flag Day) in an organized way in which all students take part."}, {"ar": "توزيع الأدوار والمسؤوليات على منسوبي المدرسة؛ لضمان جودة التطبيق، مع المتابعة وتقديم التغذية الراجعة.", "en": "Distribute roles and responsibilities among school staff to ensure quality of implementation, with follow-up and feedback."}, {"ar": "تفعيل الشراكة مع أولياء الأمور والمجتمع المحلي؛ لدعم القيم الإسلامية والهوية الوطنية.", "en": "Activate partnership with parents and the local community to support Islamic values and national identity."}], "1-2-1-2": [{"ar": "تنفيذ إجراءات واضحة لنشر قواعد السلوك الوظيفي، وقيم مهنة التعليم وأخلاقياتها، في المجتمع المدرسي.", "en": "Implement clear procedures to disseminate the professional code of conduct and the values and ethics of the teaching profession in the school community."}, {"ar": "تنفيذ برامج توعوية شاملة عن قيمة مهنة التعليم وأخلاقياتها بشكل مستمر.", "en": "Continuously implement comprehensive awareness programs about the value and ethics of the teaching profession."}, {"ar": "تنفيذ برامج وأنشطة متنوعة تعزز العلاقات الإيجابية القائمة على الاحترام المتبادل، والتعاون، والثقة بين منسوبي المدرسة.", "en": "Implement varied programs and activities that foster positive relationships based on mutual respect, cooperation and trust among school staff."}, {"ar": "متابعة التزام منسوبي المدرسة بقيم مهنة التعليم وأخلاقياتها بشكل مستمر.", "en": "Continuously monitor school staff's adherence to the values and ethics of the teaching profession."}, {"ar": "تقديم حوافز متنوعة لتشجيع منسوبي المدرسة على تطبيق قواعد السلوك الوظيفي، وأخلاقيات مهنة التعليم داخل المجتمع المدرسي وخارجه.", "en": "Provide varied incentives to encourage school staff to apply the professional code of conduct and the ethics of the teaching profession inside and outside the school community."}, {"ar": "تنفيذ إجراءات رسمية للمساءلة بشأن مخالفات قيم مهنة التعليم وأخلاقياتها.", "en": "Implement formal accountability procedures for violations of the values and ethics of the teaching profession."}, {"ar": "تنفيذ إجراءات عملية لضمان التزام جميع منسوبي المدرسة بقواعد السلوك الوظيفي، وقيم مهنة التعليم.", "en": "Implement practical procedures to ensure that all school staff comply with the professional code of conduct and the values of the teaching profession."}, {"ar": "توثيق نتائج متابعة الالتزام بقيم مهنة التعليم وأخلاقياتها بصورة دورية، وتحليلها؛ لتحديد جوانب التحسين واتخاذ الإجراءات اللازمة لتعزيز الالتزام.", "en": "Periodically document and analyze the results of monitoring adherence to the values and ethics of the teaching profession, to identify improvement areas and take the necessary actions to strengthen compliance."}], "1-2-1-3": [{"ar": "اعتماد حزمة إجراءات الانضباط المدرسي في المدرسة (وقائية/علاجية/تصحيحية) وفق قواعد السلوك والمواظبة، وتعميمها على جميع منسوبي المجتمع المدرسي والأسرة.", "en": "Adopt a package of school discipline procedures (preventive/remedial/corrective) in line with the behavior and attendance rules, and circulate it to all members of the school community and to families."}, {"ar": "إعداد إجراءات واضحة ومتنوعة وتنفيذها؛ لنشر قواعد السلوك والمواظبة في المجتمع المدرسي والمجتمع المحلي.", "en": "Prepare and implement clear and varied procedures to disseminate the behavior and attendance rules in the school and local communities."}, {"ar": "إعداد وتنفيذ خطة وقائية داعمة للانضباط المدرسي تتضمن التوعية والتدخل المبكر ورصد مؤشرات الخطورة داخل البيئة المدرسية.", "en": "Prepare and implement a preventive plan supporting school discipline that includes awareness, early intervention and monitoring of risk indicators within the school environment."}, {"ar": "تنفيذ برامج توعوية دورية لترسيخ قواعد السلوك والانضباط داخل المجتمع المدرسي.", "en": "Implement periodic awareness programs to entrench the rules of behavior and discipline within the school community."}, {"ar": "تطبيق إجراءات تعزيز السلوك الإيجابي داخل المدرسة وربطها بحوافز تربوية داعمة للانضباط.", "en": "Apply procedures to reinforce positive behavior within the school and link them to educational incentives that support discipline."}, {"ar": "تطبيق إجراءات ضبط المخالفات السلوكية وفق التدرج المناسب، وتحديد الإجراء المتخذ بناءً على طبيعة المخالفة وتكرارها ضمن إطار القواعد المعتمدة.", "en": "Apply procedures to address behavioral violations with appropriate progression, determining the action taken based on the nature and recurrence of the violation within the approved rules."}, {"ar": "متابعة شواهد الالتزام (حصر الغيابات، والمخالفات السلوكية، وحالات الانضباط)، ودراسة أسباب الغياب وتحليلها، وإعداد خطط لمعالجة الغياب بالشراكة مع الأسرة.", "en": "Monitor evidence of compliance (counting absences, behavioral violations and discipline cases), study and analyze the causes of absence, and prepare plans to address absence in partnership with families."}, {"ar": "توثيق إجراءات الانضباط والمخالفات والسجلات المرتبطة بها في الأنظمة التقنية المعتمدة وفق آلية رسمية، وإعداد تقرير مفصل بالإجراءات والخدمات المقدمة لمعالجة حالات الانضباط ورفعه للجهات ذات العلاقة وفق التسلسل التنظيمي، مع مراجعة دورية لنتائج الالتزام وإصدار ما يلزم من إجراءات تعزيز/تصحيح لضمان الاستمرارية والالتزام.", "en": "Document discipline procedures, violations and related records in the approved technical systems through a formal mechanism, prepare a detailed report on the procedures and services provided to address discipline cases and submit it to the relevant bodies following the organizational chain, with periodic review of compliance results and issuing the necessary reinforcement/corrective actions to ensure continuity and compliance."}], "1-2-1-4": [{"ar": "إعداد إجراءات محددة وتنفيذها؛ للكشف المبكر عن المشكلات السلوكية لدى المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون.", "en": "Prepare and implement specific procedures for the early detection of behavioral problems among learners, including learners with disabilities and gifted learners."}, {"ar": "إعداد خطة مدرسية وتنفيذها؛ لتعزيز السلوك الإيجابي لدى المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون، وفق احتياجاتهم.", "en": "Prepare and implement a school plan to strengthen positive behavior among learners, including learners with disabilities and gifted learners, according to their needs."}, {"ar": "تطبيق برامج وأنشطة توعوية ووقائية وعلاجية؛ لتعزيز السلوك الإيجابي والحد من السلوكيات السلبية.", "en": "Apply awareness, preventive and remedial programs and activities to strengthen positive behavior and reduce negative behaviors."}, {"ar": "تصميم البرامج والأنشطة التربوية الداعمة للسلوك الإيجابي؛ بحيث تكون مرتبطة بنتائج تشخيص المشكلات السلوكية.", "en": "Design educational programs and activities that support positive behavior, linked to the results of diagnosing behavioral problems."}, {"ar": "متابعة نتائج تطبيق البرامج والأنشطة، وقياس أثرها بشكل دوري.", "en": "Follow up the results of implementing the programs and activities and measure their impact periodically."}, {"ar": "مراعاة شمول البرامج والأنشطة لجميع المتعلمين؛ بمن فيهم ذوو الإعاقة والموهوبون، وفق احتياجاتهم.", "en": "Ensure that the programs and activities include all learners, including learners with disabilities and gifted learners, according to their needs."}, {"ar": "تقديم حوافز متنوعة لتعزيز السلوك الإيجابي لدى المتعلمين.", "en": "Provide varied incentives to strengthen positive behavior among learners."}, {"ar": "التواصل بشكل مستمر مع الأسرة؛ لمناقشة المشكلات السلوكية وتقديم الحلول لمعالجتها.", "en": "Communicate continuously with the family to discuss behavioral problems and offer solutions to address them."}], "1-2-1-5": [{"ar": "إعداد خطة متكاملة للأنشطة الإثرائية الصفية وغير الصفية وتنفيذها، وفق الأنظمة والتعليمات.", "en": "Prepare and implement an integrated plan for classroom and non-classroom enrichment activities, in accordance with regulations and instructions."}, {"ar": "تنفيذ أنشطة إثرائية غير صفية متنوعة شاملة لجميع المتعلمين، ومنهم ذوو الإعاقة والموهوبون، مع تقديم حوافز تشجيعية عينية أو معنوية، تشجعهم على المشاركة في الأنشطة، مع متابعة تنفيذ الأنشطة والبرامج بشكل مستمر.", "en": "Implement varied non-classroom enrichment activities that include all learners, including learners with disabilities and gifted learners, with tangible or moral incentives that encourage them to participate, while continuously monitoring the implementation of activities and programs."}, {"ar": "تطبيق أساليب للكشف عن مواهب وقدرات المتعلمين، وربط البرامج والأنشطة بنتائج تشخيص مواهبهم وقدراتهم.", "en": "Apply methods to identify learners' talents and abilities, and link programs and activities to the results of diagnosing their talents and abilities."}, {"ar": "تنفيذ برامج وأنشطة متنوعة؛ لتطوير مواهب المتعلمين وقدراتهم.", "en": "Implement varied programs and activities to develop learners' talents and abilities."}, {"ar": "تطبيق أساليب متنوعة؛ لتحفيز المتعلمين على المشاركة في مقياس موهبة، وتدعم مواهب المتعلمين، وتشجعهم على التميز.", "en": "Apply varied methods to motivate learners to take part in the Mawhiba scale, support learners' talents, and encourage them to excel."}, {"ar": "نشر الوعي والثقافة في المجتمع المدرسي والمجتمع المحلي، عن المسابقات الوطنية والدولية، وطرق المشاركة فيها.", "en": "Spread awareness and culture in the school and local communities about national and international competitions and ways to participate in them."}, {"ar": "تقديم حوافز متنوعة تشجع المتعلمين على المشاركة في المسابقات الوطنية والدولية، وتقديم الدعم الكامل للمشاركين في المسابقات الوطنية والدولية، مع أهمية الاحتفاء بمنجزات المتعلمين ومنسوبي المدرسة في المسابقات الوطنية والدولية.", "en": "Provide varied incentives that encourage learners to take part in national and international competitions, give full support to participants, and celebrate the achievements of learners and school staff in them."}, {"ar": "تنفيذ برامج إثرائية وأنشطة متنوعة، شاملة لجميع المتعلمين في المرحلة الثانوية بمن فيهم ذوو الإعاقة، وذلك لتهيئة المتعلمين في هذه المرحلة لمستقبلهم الأكاديمي، مع تقديم حوافز تشجع المتعلمين على المشاركة في هذه الأنشطة والبرامج، وتفعيل شراكات مع مؤسسات المجتمع ذات العلاقة في هذا الجانب.", "en": "Implement enrichment programs and varied activities for all learners in the secondary stage, including learners with disabilities, to prepare them for their academic future, with incentives encouraging participation in these activities and programs, and by activating partnerships with relevant community institutions in this area."}], "1-3-1-1": [{"ar": "إعداد خطة متكاملة لتعزيز العمل التعاوني بين منسوبي المدرسة، وتنفيذها، ومراجعتها دورياً.", "en": "Prepare an integrated plan to strengthen collaborative work among school staff, implement it, and review it periodically."}, {"ar": "تضمين أنشطة ومهام في الخطة تشجع التعاون والعمل بروح الفريق.", "en": "Include in the plan activities and tasks that encourage cooperation and teamwork."}, {"ar": "شمول جميع منسوبي المدرسة في تنفيذ الأنشطة والمهام التعاونية.", "en": "Involve all school staff in carrying out the collaborative activities and tasks."}, {"ar": "تعزيز العمل الجماعي بأساليب وطرائق مبتكرة داخل المدرسة.", "en": "Strengthen teamwork within the school through innovative methods and approaches."}, {"ar": "متابعة أثر تطبيق برامج التعاون والعمل الجماعي من خلال أدوات قياس الرضا.", "en": "Follow up the impact of the cooperation and teamwork programs through satisfaction measurement tools."}], "1-3-1-2": [{"ar": "تنفيذ أنشطة وبرامج متنوعة للتوعية بدور الأسرة في تعلم أبنائها والتحضير لمستقبلهم.", "en": "Implement varied activities and programs to raise awareness of the family's role in their children's learning and in preparing for their future."}, {"ar": "الاستمرار في تنفيذ الأنشطة والبرامج بشكل منتظم، على أن تشمل المجتمع المدرسي وأولياء الأمور والأسر.", "en": "Continue implementing the activities and programs regularly, covering the school community, parents and families."}, {"ar": "مشاركة الأسرة في تقويم تعلم أبنائها، ومتابعة أداء المهام والواجبات.", "en": "Engage the family in evaluating their children's learning and in following up on tasks and assignments."}, {"ar": "مشاركة الأسرة في تحديد المشكلات التي تواجه تعلم أبنائها، وتقديم الحلول المناسبة.", "en": "Engage the family in identifying the problems facing their children's learning and in proposing suitable solutions."}, {"ar": "تقديم حوافز تدعم مشاركة الأسرة في الأنشطة والبرامج لدعم تعلم أبنائها.", "en": "Provide incentives that support family participation in activities and programs that support their children's learning."}, {"ar": "تفعيل أساليب وطرق متنوعة للتواصل مع الأسرة بشكل مستمر، وتزويدها بمعلومات وبيانات عن تعلم أبنائها وكيفية دعمهم.", "en": "Activate varied methods of continuous communication with the family, providing information and data on their children's learning and how to support them."}, {"ar": "إتاحة الفرصة لمشاركة الأسرة في الأنشطة والفعاليات التي تنفذها المدرسة (استثمار خبرات الوالدين التخصصية).", "en": "Provide opportunities for families to take part in the school's activities and events (drawing on parents' specialist expertise)."}, {"ar": "مشاركة الأسرة في تقويم خدمات المدرسة التعليمية وتطويرها.", "en": "Engage the family in evaluating and developing the school's educational services."}], "1-3-1-3": [{"ar": "تفعيل أساليب وطرق متنوعة للتواصل والتعاون مع مؤسسات المجتمع لدعم تعلم المتعلمين وتلبية احتياجات ذوي الإعاقة والموهوبين، وذلك بشكل مستمر.", "en": "Activate varied methods of communication and cooperation with community institutions, on an ongoing basis, to support learners' learning and meet the needs of learners with disabilities and gifted learners."}, {"ar": "تنفيذ برامج وأنشطة لتوعية المجتمع المدرسي والمجتمع المحلي بأهمية مشاركة مؤسسات المجتمع في تعزيز عملية التعلم.", "en": "Implement programs and activities that raise awareness in the school and local communities of the importance of community institutions' participation in strengthening learning."}, {"ar": "عقد شراكات مجتمعية مع المؤسسات الوطنية (مثل: المؤسسات والمراكز ذات العلاقة بالموهبة والإبداع وذوي الإعاقة).", "en": "Establish community partnerships with national institutions (e.g. institutions and centers related to talent, creativity and disability)."}, {"ar": "دعم تبادل الخبرات ونقل المعرفة مع المدارس الأخرى لتعزيز التعلم (زيارات مدرسية، واجتماعات عمل، وتطوير مهني مشترك، إلخ).", "en": "Support the exchange of expertise and knowledge transfer with other schools to strengthen learning (school visits, working meetings, joint professional development, etc.)."}, {"ar": "تنفيذ أنشطة وبرامج لتعريف المجتمع المدرسي بالخدمات التي تقدمها المؤسسات ذات العلاقة بالموهوبين وذوي الإعاقة.", "en": "Implement activities and programs that familiarize the school community with the services offered by institutions concerned with gifted learners and learners with disabilities."}, {"ar": "الاستفادة من الخدمات التي تقدمها المؤسسات ذات العلاقة بالموهوبين وذوي الإعاقة بأساليب وطرق متنوعة، وتوثيق جميع الشراكات.", "en": "Make use of the services offered by these institutions through varied methods, and document all partnerships."}, {"ar": "تقديم الدعم والمساندة للمؤسسات الوطنية التي تعنى بتلبية احتياجات ذوي الإعاقة والموهوبين.", "en": "Provide support and assistance to national institutions that work to meet the needs of learners with disabilities and gifted learners."}, {"ar": "تقديم خدمات متنوعة (الأندية الرياضية، والبرامج التدريبية، والمكتبة، والمسرح، ...) للمجتمع المحلي.", "en": "Offer varied services (sports clubs, training programs, the library, the theater, etc.) to the local community."}], "1-4-1-1": [{"ar": "تنفيذ آليات وإجراءات واضحة ومعلنة لاستقطاب الكوادر التعليمية المؤهلة.", "en": "Implement clear, publicly announced mechanisms and procedures for attracting qualified teaching staff."}, {"ar": "التعاقد مع كادر تعليمي مكتمل (عدد المعلمين يغطي جميع المجالات التخصصية).", "en": "Contract a complete teaching staff (the number of teachers covers all specialization areas)."}, {"ar": "التعاقد مع كادر تعليمي مؤهل (90% فأكثر من الكادر التعليمي بكالوريوس فأعلى).", "en": "Contract a qualified teaching staff (90% or more of teaching staff hold a bachelor's degree or higher)."}, {"ar": "رفع توافق مؤهل وخبرة الكادر التعليمي مع المجال التخصصي الذي يدرّسه إلى (90% فأكثر) من الكادر التعليمي.", "en": "Raise the match between teaching staff's qualifications and experience and the subject they teach to 90% or more of the teaching staff."}], "1-4-1-2": [{"ar": "تنفيذ آليات واضحة وإجراءات معلنة لاستقطاب الكوادر الإدارية المؤهلة.", "en": "Implement clear mechanisms and announced procedures for attracting qualified administrative staff."}, {"ar": "التعاقد مع كادر إداري مكتمل وفقاً لحجم المدرسة.", "en": "Contract a complete administrative staff according to the size of the school."}, {"ar": "التعاقد مع كادر إداري مؤهل (90% فأكثر من الكادر الإداري دبلوم مشارك فأعلى).", "en": "Contract a qualified administrative staff (90% or more of administrative staff hold an associate diploma or higher)."}, {"ar": "رفع توافق مؤهل وخبرة الكادر الإداري مع العمل المكلف به إلى (90% فأكثر) من الكادر الإداري.", "en": "Raise the match between administrative staff's qualifications and experience and their assigned work to 90% or more of the administrative staff."}, {"ar": "تعزيز التحفيز والتقدير للكادر الإداري المتميز لضمان استدامة الأداء الفاعل.", "en": "Strengthen motivation and recognition for outstanding administrative staff to ensure sustained effective performance."}, {"ar": "تطبيق نظام متابعة وتقويم دوري لقياس فاعلية الكادر الإداري ومدى توافقه مع متطلبات العمل المكلف به.", "en": "Apply a periodic monitoring and evaluation system to measure administrative staff's effectiveness and their fit with the requirements of their assigned work."}], "1-4-1-3": [{"ar": "إعداد وتنفيذ خطة مالية سنوية وتقرير مالي معتمد، يتضمن توثيق جميع المعاملات (دخل وصرف)، ويُراجَع ويُحدَّث بشكل دوري بمشاركة أصحاب العلاقة؛ لضمان الاستدامة المالية.", "en": "Prepare and implement an annual financial plan and an approved financial report that documents all transactions (income and expenditure), and is reviewed and updated periodically with stakeholder participation to ensure financial sustainability."}, {"ar": "توزيع الموارد المالية وفق الخطة التشغيلية، وبما يتناسب مع أولويات المدرسة؛ لزيادة الفاعلية التعليمية وتحقيق أهدافها.", "en": "Distribute financial resources according to the operational plan and in line with the school's priorities, to increase educational effectiveness and achieve its goals."}, {"ar": "تخصيص بند من الميزانية لعمليات التطوير المهني وبرامجه.", "en": "Allocate a budget item for professional development processes and programs."}, {"ar": "تطبيق إجراءات واضحة وضوابط للمراجعة والتدقيق، مع توثيق الموارد المالية وعمليات الدخل والصرف، وإعداد تقارير مالية دورية، إضافة إلى اعتماد آليات وضوابط دقيقة لعمليات الصرف، وآليات واضحة للمساءلة.", "en": "Apply clear procedures and controls for review and audit, documenting financial resources and income and expenditure operations, preparing periodic financial reports, and adopting precise mechanisms and controls for spending as well as clear accountability mechanisms."}, {"ar": "الالتزام بتغطية جميع مصروفات المدرسة التشغيلية من مواردها المالية، بما يحقق التوافق بين الإيرادات والمصروفات وفق الخطة التشغيلية، مع تطبيق إجراءات واضحة للمراجعة والتدقيق بشكل مستمر، وضوابط لمتابعة الالتزامات المالية، وإعداد التقارير المالية الدورية التي تُظهر التنوع في الموارد والنمو في الإيرادات، مع توافر احتياطي مالي لتغطية المصروفات الطارئة.", "en": "Commit to covering all of the school's operating expenses from its own financial resources, achieving alignment between revenues and expenses per the operational plan, with continuous clear review and audit procedures, controls for monitoring financial obligations, and periodic financial reports showing diversity of resources and growth in revenue, together with a financial reserve to cover emergency expenses."}, {"ar": "الالتزام بوضع سياسات وضوابط واضحة للرسوم وإجراءات التحصيل بمشاركة أصحاب المصلحة في صياغتها واعتمادها، ونشرها بوسائل وأساليب متعددة، وإبلاغ أولياء الأمور بالرسوم وإجراءات الدفع بطرق متنوعة وموثقة، وتوفير برامج توعوية لشرح سياسات التحصيل، والإعلان عن التغييرات في الرسوم قبل بداية العام الدراسي بمدة كافية، مع متابعة عمليات دفع الرسوم بشكل مستمر وموثق.", "en": "Commit to establishing clear fee policies and collection procedures, with stakeholders participating in drafting and approving them; publish them through multiple means; notify parents of fees and payment procedures through varied, documented channels; provide awareness programs explaining collection policies; announce fee changes sufficiently ahead of the academic year; and monitor fee payments continuously and with documentation."}], "1-4-1-4": [{"ar": "إعداد خطة تستهدف تقديم الدعم المستمر للمعلمين وتنفيذها؛ لتحقيق نسبة 90% من المعلمين الحاصلين على الرخصة المهنية، مع أهمية حصول بعض المعلمين على رخصة متقدم وخبير.", "en": "Prepare and implement a plan for continuous support to teachers so that 90% of teachers hold the professional license, with some teachers also obtaining the advanced and expert licenses."}, {"ar": "تنفيذ أنشطة وبرامج متنوعة (توعوية وإرشادية) وشاملة لجميع التخصصات حول أهمية الرخصة المهنية.", "en": "Implement varied awareness and guidance activities and programs, covering all specializations, on the importance of the professional license."}, {"ar": "تقديم حوافز لتشجيع المعلمين على الحصول على الرخصة المهنية.", "en": "Provide incentives to encourage teachers to obtain the professional license."}, {"ar": "توفير الدعم الفني والإرشادي للمعلمين أثناء مراحل التقديم والاختبار (ورش تعريفية، ومجموعات تعلم مهنية).", "en": "Provide technical and advisory support to teachers during the application and testing stages (orientation workshops and professional learning groups)."}, {"ar": "تحليل نتائج اختبارات الرخصة المهنية بشكل دوري لتحديد الاحتياجات التدريبية ووضع خطط التحسين المناسبة.", "en": "Periodically analyze professional license test results to identify training needs and set suitable improvement plans."}], "1-4-1-5": [{"ar": "إعداد خطة تطوير مهني تشمل جميع منسوبي المدرسة، وترتبط بنتائج تقويم الأداء الوظيفي، وتلبي احتياجات منسوبي المدرسة، مع أهمية مشاركتهم في تحديد الاحتياجات.", "en": "Prepare a professional development plan covering all school staff, linked to performance appraisal results and meeting staff needs, with staff taking part in identifying those needs."}, {"ar": "نشر الوعي بأهمية التطوير المهني في تطوير الممارسات، وأنواعه، وكيفية المشاركة فيه.", "en": "Raise awareness of the importance of professional development in improving practice, its types, and how to take part."}, {"ar": "تنفيذ برامج وأنشطة متنوعة للتطوير المهني بصورة مستمرة، مع أهمية متابعة التنفيذ.", "en": "Continuously implement varied professional development programs and activities, with follow-up of implementation."}, {"ar": "استخدام أساليب متنوعة وطرائق مستمرة لدعم منسوبي المدرسة على المشاركة في برامج التطوير المهني والالتحاق بالبرامج التدريبية.", "en": "Use varied, ongoing methods to support school staff in taking part in professional development programs and enrolling in training programs."}, {"ar": "تشجيع منسوبي المدرسة على المشاركة في المؤتمرات العلمية والملتقيات والندوات، وفي إجراء الدراسات والبحوث الإجرائية.", "en": "Encourage school staff to take part in scientific conferences, forums and seminars, and to conduct studies and action research."}, {"ar": "الاستفادة من التقنية الرقمية في التطوير المهني المستمر.", "en": "Make use of digital technology in continuous professional development."}, {"ar": "بناء مجتمعات التعلم المهني في المدرسة، وتشجيع منسوبي المدرسة على مشاركة خبراتهم وأفكارهم وتجاربهم التعليمية وتبادلها فيما بينهم، مع أهمية تقديم حوافز لتعزيز المشاركة في مجتمعات التعلم المهنية.", "en": "Build professional learning communities in the school, encouraging staff to share and exchange their experiences, ideas and teaching practices, with incentives to strengthen participation in these communities."}, {"ar": "تطبيق أساليب متنوعة لقياس أثر التدريب بانتظام.", "en": "Apply varied methods to measure the impact of training regularly."}], "1-4-1-6": [{"ar": "نشر ثقافة التقويم الذاتي في المجتمع المدرسي والمجتمع المحلي بطرق وأساليب متنوعة.", "en": "Spread a culture of self-evaluation in the school and local communities through varied methods."}, {"ar": "إعداد خطة إجرائية لتطبيق التقويم الذاتي وتنفيذها.", "en": "Prepare and implement an operational plan for applying self-evaluation."}, {"ar": "تشكيل فريق التقويم الذاتي وفق المعايير المحددة في دليل التقويم الذاتي.", "en": "Form the self-evaluation team according to the criteria set out in the self-evaluation guide."}, {"ar": "عقد اجتماعات ولقاءات وتنفيذ ورش عمل لتهيئة المجتمع المدرسي للتقويم الذاتي.", "en": "Hold meetings and sessions and run workshops to prepare the school community for self-evaluation."}, {"ar": "تطبيق جميع إجراءات التقويم الذاتي بشكل منظم، مع أهمية التقيد بمعايير ومؤشرات التقويم والاعتماد المدرسي في عمليات التقويم.", "en": "Apply all self-evaluation procedures in an organized manner, adhering to the school evaluation and accreditation standards and indicators."}, {"ar": "توثيق جميع إجراءات وعمليات التقويم الذاتي.", "en": "Document all self-evaluation procedures and processes."}, {"ar": "إشراك منسوبي المدرسة وأصحاب المصلحة في التقويم الذاتي.", "en": "Involve school staff and stakeholders in self-evaluation."}, {"ar": "اطلاع منسوبي المدرسة وأصحاب المصلحة على نتائج التقويم الذاتي بانتظام.", "en": "Inform school staff and stakeholders of self-evaluation results regularly."}], "1-4-1-7": [{"ar": "تحليل نتائج التقويم المدرسي، وتحديد نقاط القوة وفرص التحسين، وترتيب المجالات والمؤشرات من حيث أولوية التحسين.", "en": "Analyze school evaluation results, identify strengths and improvement opportunities, and rank domains and indicators by improvement priority."}, {"ar": "إعداد خطة التحسين بحيث تكون مكتملة العناصر، وتتضمن: أهدافاً محددة، وبرامج وأنشطة مزمنة، ومبادرات نوعية، وإجراءات تنفيذ واضحة، مع تحديد الأدوار والمسؤوليات ومؤشرات الإنجاز، مع أهمية مشاركة أكثر من 90% من الكادر التعليمي في إعداد الخطة.", "en": "Prepare a fully elaborated improvement plan that includes specific goals, time-bound programs and activities, qualitative initiatives and clear implementation procedures, with defined roles, responsibilities and achievement indicators, and with more than 90% of teaching staff taking part in preparing it."}, {"ar": "تصميم البرامج والأنشطة والمبادرات في خطة التحسين بحيث تغطي جميع المجالات الأولى بالتحسين، وكل برنامج يتضمن خطوات تنفيذ واضحة، مع تحديد المسؤوليات والموارد والجدول الزمني والفئات المستهدفة.", "en": "Design the programs, activities and initiatives in the improvement plan so that they cover all priority areas for improvement, each program having clear implementation steps, with defined responsibilities, resources, timeline and target groups."}, {"ar": "تنفيذ خطة التحسين مع المتابعة المستمرة.", "en": "Implement the improvement plan with continuous follow-up."}, {"ar": "تقييم خطة التحسين بشكل منتظم، مع رصد المشكلات والتحديات، وتقديم الحلول والبدائل.", "en": "Evaluate the improvement plan regularly, tracking problems and challenges and offering solutions and alternatives."}, {"ar": "تطوير خطة التحسين بشكل مستمر.", "en": "Continuously develop the improvement plan."}], "1-5-1-1": [{"ar": "اعتماد إجراءات حماية حقوق المتعلمين وحمايتهم داخل المدرسة، وتعميمها على منسوبي المدرسة والطلبة وأولياء الأمور، والتأكيد على عدم التسامح مع أي إيذاء أو إساءة أو تمييز.", "en": "Adopt procedures to protect learners' rights and safeguard them within the school, circulate them to staff, students and parents, and stress zero tolerance of any harm, abuse or discrimination."}, {"ar": "تنفيذ برامج توعوية دورية بحقوق المتعلمين وسبل الحماية (العنف/الإهمال/التنمر)، وتوضيح آليات الإبلاغ وطلب المساعدة داخل المدرسة وخارجها.", "en": "Run periodic awareness programs on learners' rights and means of protection (violence/neglect/bullying), clarifying how to report and seek help inside and outside the school."}, {"ar": "تطبيق قواعد السلوك والمواظبة بما يضمن حفظ حقوق المتعلمين داخل البيئة المدرسية، وتعزيز السلوك الإيجابي والحد من السلوكيات التي تمس السلامة أو الكرامة.", "en": "Apply the rules of conduct and attendance in a way that safeguards learners' rights in the school environment, promoting positive behavior and limiting behaviors that affect safety or dignity."}, {"ar": "تفعيل إجراءات الرصد المبكر لمؤشرات الخطر (عنف/تنمر/إهمال/مشكلات سلوكية حادة) وإحالتها وفق النماذج المعتمدة داخل المدرسة.", "en": "Activate early-detection procedures for risk indicators (violence/bullying/neglect/severe behavioral problems) and refer cases using the school's approved forms."}, {"ar": "تنفيذ إجراءات التبليغ الرسمية عند الاشتباه أو التحقق، وفق ما تقرره الأدلة والأنظمة (مثل: تبليغ إدارة التعليم، والجهات الأمنية عند الحاجة، وجهات حماية الطفل/العنف الأسري، والجهات الصحية).", "en": "Carry out official reporting procedures upon suspicion or confirmation, as the guides and regulations require (e.g. reporting to the education department, security authorities when needed, child protection/domestic violence bodies, and health authorities)."}, {"ar": "ضمان توثيق الحالات والإجراءات المتخذة وحفظ السجلات بسرية، وتحديد صلاحيات الاطلاع وفق الضوابط.", "en": "Ensure that cases and the actions taken are documented, records are kept confidential, and access permissions are defined according to the rules."}, {"ar": "تطبيق تكييفات وإجراءات حماية شاملة تراعي جميع المتعلمين (ومنهم ذوو الإعاقة والموهوبون) في البرامج والأنشطة والإشراف والبيئة الآمنة، بما يمنع أي تمييز أو إقصاء.", "en": "Apply inclusive accommodations and protection procedures that take all learners into account (including learners with disabilities and gifted learners) in programs, activities, supervision and a safe environment, preventing any discrimination or exclusion."}, {"ar": "مراجعة دورية لالتزام المدرسة بإجراءات حماية الحقوق والحماية (شهرياً/فصلياً)، وتحليل الملاحظات والحالات، وإصدار تحسينات وإجراءات تصحيحية؛ لضمان الاستمرارية ورفع مستوى الأمان.", "en": "Periodically review the school's compliance with rights-protection and safeguarding procedures (monthly/termly), analyze observations and cases, and issue improvements and corrective actions to ensure continuity and raise the level of safety."}], "1-5-1-2": [{"ar": "تنفيذ برامج وقائية تهدف إلى الحد من المشكلات السلوكية والنفسية داخل المدرسة.", "en": "Implement preventive programs aimed at reducing behavioral and psychological problems within the school."}, {"ar": "تنفيذ برامج صفية وأنشطة لاصفية متنوعة تعزز الجانب التربوي والاجتماعي للمتعلمين.", "en": "Implement varied classroom programs and extracurricular activities that strengthen learners' educational and social development."}, {"ar": "تنظيم ندوات تثقيفية للتوعية بالقيم الإيجابية وطرق التعامل مع الضغوط.", "en": "Organize educational seminars to raise awareness of positive values and ways of coping with stress."}, {"ar": "تشجيع المتعلمين على الحوار والمناقشة، وقبول الرأي الآخر في المواقف الصفية والأنشطة غير الصفية.", "en": "Encourage learners to engage in dialogue and discussion and to accept other opinions in classroom situations and extracurricular activities."}, {"ar": "تعزيز التعاون والعلاقات الإيجابية بين المتعلمين والمعلمين، بما يرسخ الاحترام المتبادل.", "en": "Strengthen cooperation and positive relationships between learners and teachers, reinforcing mutual respect."}, {"ar": "تنفيذ برامج (وقائية وإرشادية وعلاجية) لحالات التنمر والعنف.", "en": "Implement preventive, guidance and remedial programs for cases of bullying and violence."}, {"ar": "توفير الاستشارات والدعم النفسي والاجتماعي للمتعلمين بشكل مستمر.", "en": "Provide counseling and psychological and social support to learners on a continuous basis."}, {"ar": "إبراز نتائج أعمال مجالس الحوار الطلابية وتوظيفها في تحسين المناخ المدرسي.", "en": "Highlight the outcomes of student dialogue councils and use them to improve the school climate."}], "2-1-1-1": [{"ar": "تنويع الأنشطة ومصادر التعلم (بصرية، وسمعية، وحسية) في بيئة التعلم وتنظيمها بحيث: (1) تلبي احتياجات جميع المتعلمين، ومنهم ذوو الإعاقة والموهوبون وسريعو التعلم؛ (2) تناسب خصائص المرحلة العمرية؛ (3) تراعي الفروق الفردية بين الطلاب؛ (4) وتحقق سهولة الوصول والاستخدام.", "en": "Diversify learning activities and resources (visual, auditory and tactile) in the learning environment and organize them so that they: (1) meet the needs of all learners, including learners with disabilities, gifted and fast learners; (2) suit the characteristics of the age stage; (3) take individual differences among students into account; and (4) are easy to access and use."}, {"ar": "إدارة الوقت بفاعلية وكفاءة لدعم عملية التعلم بحيث يتم: (1) توزيع الوقت على أنشطة الدرس ومراحله وتجنب التشتيت؛ (2) مراعاة نوع المادة العلمية ومستوى التعقيد؛ (3) التوافق بين عدد الأنشطة وأسلوب تنفيذها مع الوقت المخصص؛ (4) المرونة في إدارة الوقت وفقاً للموقف التعليمي؛ (5) إتاحة الوقت الكافي لجميع المتعلمين لتنفيذ الأنشطة والمناقشة؛ (6) مراعاة الفروق الفردية بين الطلاب في توزيع الوقت.", "en": "Manage time effectively and efficiently to support learning so that: (1) time is distributed across lesson activities and stages while avoiding distraction; (2) the type of subject matter and its complexity are considered; (3) the number of activities and how they are carried out fit the allotted time; (4) time management is flexible according to the teaching situation; (5) all learners are given enough time to carry out activities and discuss; (6) individual differences among students are considered in distributing time."}, {"ar": "إتاحة فرص متكافئة للمتعلمين في عملية التعلم من خلال: (1) المشاركة في الأنشطة المتنوعة؛ (2) استخدام مصادر التعلم والاستفادة منها؛ (3) المناقشة والحوار في الأنشطة الصفية؛ (4) الاستفادة من أساليب التحفيز والتشجيع والدعم.", "en": "Provide learners with equal opportunities in the learning process through: (1) taking part in varied activities; (2) using and benefiting from learning resources; (3) discussion and dialogue in classroom activities; (4) benefiting from methods of motivation, encouragement and support."}], "2-1-1-2": [{"ar": "تزويد المعلمين بالخطة الدراسية للعام الدراسي، وأخذ التوقيعات بالعلم.", "en": "Provide teachers with the study plan for the academic year and obtain signatures of acknowledgment."}, {"ar": "يُعِدّ كل معلم خطة توزيع المنهج الدراسي في بداية العام الدراسي، بهدف تنظيم تنفيذ المحتوى الزمني للوحدات التعليمية، بما يضمن تحقيق الأهداف المعرفية والمهارية والقيمية.", "en": "Each teacher prepares a curriculum distribution plan at the start of the academic year, to organize the timing of delivering the learning units so as to achieve the knowledge, skill and value objectives."}, {"ar": "توفير أنشطة شاملة ومصادر متنوعة لدعم تعلم جميع موضوعات ومحتوى المنهج، مع التركيز على المعارف الرئيسة والمهارات النوعية والقيم الوطنية.", "en": "Provide comprehensive activities and varied resources to support learning of all curriculum topics and content, focusing on core knowledge, specific skills and national values."}, {"ar": "المتابعة الدائمة لتنفيذ المنهج وفق الخطة الزمنية، وتحقيق نواتج التعلم المستهدفة وفق الخطة الدراسية.", "en": "Continuously follow up curriculum delivery according to the timeline, and the achievement of targeted learning outcomes according to the study plan."}, {"ar": "متابعة عمليات التنفيذ بشكل مستمر، وتحديد المشكلات، وتقديم الحلول والبدائل لتنفيذ المناهج في حال التأخر.", "en": "Continuously monitor implementation, identify problems, and offer solutions and alternatives for delivering the curriculum when there is a delay."}, {"ar": "التدخل العاجل واتخاذ إجراءات مناسبة في حال لم يلتزم المعلم بالخطة.", "en": "Intervene urgently and take appropriate action if a teacher does not adhere to the plan."}, {"ar": "تنفيذ برامج التطوير المهني للمعلمين الخاصة بتنفيذ المنهج.", "en": "Implement professional development programs for teachers related to curriculum delivery."}], "2-1-1-3": [{"ar": "تشخيص احتياجات المتعلمين ومستوياتهم لتحديد الاستراتيجيات التعليمية المناسبة لكل فئة.", "en": "Diagnose learners' needs and levels in order to determine the teaching strategies suited to each group."}, {"ar": "إعداد خطة تدريسية مرنة تتضمن استراتيجيات متنوعة تراعي أنماط التعلم المختلفة.", "en": "Prepare a flexible teaching plan that includes varied strategies taking different learning styles into account."}, {"ar": "تطبيق استراتيجيات تدريس نشطة ومتنوعة متمركزة حول الطالب، تسهم في تفعيل دوره الإيجابي في التعلم وتنمية مهارات التفكير والتعلم الذاتي، وفق خصائص المتعلمين واحتياجاتهم، مع أهمية توظيف التقنية التعليمية والوسائط الرقمية لدعم تعلم الطالب وتعزيز التفاعل داخل الصف.", "en": "Apply active, varied, student-centered teaching strategies that activate the student's positive role in learning and develop thinking and self-learning skills according to learners' characteristics and needs, using educational technology and digital media to support learning and enhance classroom interaction."}, {"ar": "مراعاة الفروق الفردية عند تنفيذ الدرس من خلال تكييف الأنشطة والمهام بما يتناسب مع قدرات المتعلمين ومستوياتهم.", "en": "Take individual differences into account when delivering lessons by adapting activities and tasks to learners' abilities and levels."}, {"ar": "تقديم أنشطة إثرائية وداعمة للمتعلمين المتفوقين وذوي الإعاقة وصعوبات التعلم لضمان فرص تعلم متكافئة للجميع.", "en": "Provide enrichment and support activities for high-achieving learners, learners with disabilities and learning difficulties, to ensure equal learning opportunities for all."}, {"ar": "تفعيل أدوات التقويم التكويني لقياس مدى فاعلية الاستراتيجيات المتنوعة في تحسين نواتج التعلم.", "en": "Activate formative assessment tools to measure how effective the varied strategies are in improving learning outcomes."}, {"ar": "تبادل الخبرات بين المعلمين من خلال الزيارات الصفية والمجتمعات المهنية، لرفع كفاءة تطبيق الاستراتيجيات التعليمية المتنوعة.", "en": "Exchange expertise among teachers through classroom visits and professional communities, to raise the efficiency of applying varied teaching strategies."}, {"ar": "متابعة تنفيذ الاستراتيجيات ميدانياً، وتقديم التغذية الراجعة المستمرة لتحسين الأداء.", "en": "Follow up the implementation of strategies in the field and provide continuous feedback to improve performance."}], "2-1-1-4": [{"ar": "تعزيز الوعي بالأمن الرقمي وأخلاقيات التقنية من خلال أنشطة ومبادرات تنمي الاستخدام المسؤول للتقنية واحترام الملكية الفكرية.", "en": "Raise awareness of digital security and technology ethics through activities and initiatives that develop responsible use of technology and respect for intellectual property."}, {"ar": "توفير بيئة تعلم إلكترونية متكاملة بالتجهيزات التقنية والتطبيقات التعليمية اللازمة لتيسير دمج التعلم الصفي والإلكتروني، بما يلبي احتياجات جميع المتعلمين.", "en": "Provide an integrated e-learning environment with the necessary technical equipment and educational applications to facilitate blending classroom and online learning, meeting the needs of all learners."}, {"ar": "إعداد خطة شاملة ومرنة لدمج التقنية الرقمية في التعليم اليومي، تتضمن خطط الطوارئ وآليات المتابعة والتقويم والتحسين المستمر.", "en": "Prepare a comprehensive, flexible plan for integrating digital technology into daily teaching, including contingency plans and mechanisms for monitoring, evaluation and continuous improvement."}, {"ar": "توظيف أدوات التعلم الرقمي بفاعلية وربطها بالممارسات الصفية لدعم التعلم النشط والمستدام.", "en": "Use digital learning tools effectively and link them to classroom practice to support active and sustainable learning."}, {"ar": "تنفيذ أنشطة تعليمية رقمية متنوعة ومبتكرة تشجع استخدام التقنية في التقصي والبحث وتنمية التفكير الإبداعي وحل المشكلات، مع مراعاة الفروق الفردية.", "en": "Carry out varied, innovative digital learning activities that encourage using technology for inquiry and research and developing creative thinking and problem solving, taking individual differences into account."}, {"ar": "توظيف مصادر تعلم رقمية متعددة (وسائط تفاعلية، وتطبيقات تعليمية، ومنصات بحثية) لتلبية احتياجات المتعلمين المختلفة وتنمية مهاراتهم التقنية الرقمية.", "en": "Use multiple digital learning resources (interactive media, educational applications, research platforms) to meet learners' different needs and develop their digital technical skills."}, {"ar": "تقديم برامج دعم وإثراء رقمية للموهوبين والمتقدمين، مع خطط علاجية رقمية للمتعثرين، بما يضمن تلبية الاحتياجات التعليمية المتباينة.", "en": "Provide digital support and enrichment programs for gifted and advanced learners, with digital remedial plans for struggling learners, to ensure that diverse learning needs are met."}, {"ar": "تقديم الدعم الفني والتقني المستمر لضمان جودة التنفيذ ومعالجة التحديات أولاً بأول، مع متابعة أثر الأنشطة الرقمية وتقييمها بطرق مبتكرة لقياس تطور مهارات البحث والاستخدام الآمن للتقنية لدى المتعلمين والمعلمين، ومتابعة جودة دمج التقنية وتحسينها بانتظام.", "en": "Provide continuous technical support to ensure quality of implementation and address challenges promptly, while following up and evaluating the impact of digital activities in innovative ways to measure the development of research skills and safe technology use among learners and teachers, and regularly monitoring and improving the quality of technology integration."}], "2-1-1-5": [{"ar": "إعداد أنشطة تعلم تطبيقية متنوعة ومبتكرة وتنفيذها، ترتبط بالمواقف الحياتية الواقعية وتسهم في تعزيز مهارات التفكير العملي والإبداعي لدى المتعلمين.", "en": "Prepare and carry out varied, innovative applied learning activities linked to real-life situations that strengthen learners' practical and creative thinking skills."}, {"ar": "دمج التعلم القائم على المشاريع وحل المشكلات والاستقصاء ضمن الخطط الدراسية؛ لتشجيع المتعلمين على البحث والاستنتاج والتجريب للوصول إلى المعرفة من خلال الممارسة العملية.", "en": "Integrate project-based learning, problem solving and inquiry into study plans to encourage learners to research, infer and experiment so as to reach knowledge through hands-on practice."}, {"ar": "تفعيل المواقف التعليمية العملية داخل الصف وخارجه عبر تجارب مخبرية وزيارات ميدانية ومهام مجتمعية تحاكي الواقع.", "en": "Activate practical learning situations inside and outside the classroom through laboratory experiments, field visits and community tasks that simulate reality."}, {"ar": "توظيف التقنية والتطبيقات الرقمية التفاعلية (كالوسائط المتعددة والمحاكاة والمنصات التعليمية) لدعم تنفيذ الأنشطة التطبيقية وتعزيز تعلم الطالب الذاتي.", "en": "Use technology and interactive digital applications (such as multimedia, simulation and educational platforms) to support applied activities and strengthen students' self-learning."}, {"ar": "تهيئة بيئات تعلم محفزة للتجريب والتعاون، تتيح فرص التواصل والتعلم الجماعي وتنمي روح المبادرة لدى المتعلمين.", "en": "Create learning environments that stimulate experimentation and collaboration, offering opportunities for communication and group learning and developing a spirit of initiative in learners."}, {"ar": "متابعة تنفيذ الأنشطة التطبيقية وتقييم أثرها على مهارات التفكير العلمي والإبداع وحل المشكلات من خلال أدوات تقويم متنوعة ومؤشرات أداء واضحة.", "en": "Follow up the implementation of applied activities and evaluate their impact on scientific thinking, creativity and problem-solving skills using varied assessment tools and clear performance indicators."}, {"ar": "تطوير قدرات المعلمين على تصميم أنشطة تعلم واقعية ومبتكرة عبر برامج تدريبية ومجتمعات تعلم مهنية مستمرة.", "en": "Develop teachers' ability to design realistic, innovative learning activities through training programs and ongoing professional learning communities."}], "2-1-1-6": [{"ar": "تنفيذ برامج وأنشطة صفية ولاصفية تستهدف تنمية مهارات القراءة والكتابة والمهارات العددية من خلال ممارسات تطبيقية وواقعية تراعي الفروق الفردية بين المتعلمين.", "en": "Implement classroom and extracurricular programs and activities that develop reading, writing and numeracy skills through applied, realistic practices that take individual differences among learners into account."}, {"ar": "توظيف مصادر تعلم متنوعة وغنية تتيح فرصاً للتعلم الذاتي وتدعم اكتساب المهارات الأساسية في بيئات تعلم جاذبة ومحفزة.", "en": "Use varied, rich learning resources that offer opportunities for self-learning and support acquiring basic skills in attractive, stimulating learning environments."}, {"ar": "تنمية مهارات القراءة والفهم والتعبير الكتابي باستخدام استراتيجيات متنوعة كالاستقصاء والمناقشة وطرح الأسئلة والتعلم القائم على المشروعات.", "en": "Develop reading, comprehension and written expression skills using varied strategies such as inquiry, discussion, questioning and project-based learning."}, {"ar": "تنمية المفاهيم والمهارات العددية الأساسية من خلال أنشطة عملية وتطبيقات حياتية تشجع على التفكير الناقد وحل المشكلات.", "en": "Develop basic numeracy concepts and skills through practical activities and real-life applications that encourage critical thinking and problem solving."}, {"ar": "إعداد خطط علاجية وإثرائية مرنة وتنفيذها، تعالج جوانب الضعف وتعزز جوانب القوة، مع متابعة مستمرة لقياس الأثر والتحسين.", "en": "Prepare and implement flexible remedial and enrichment plans that address weaknesses and reinforce strengths, with continuous follow-up to measure impact and improve."}, {"ar": "تفعيل التقنية والتطبيقات الرقمية التفاعلية في تدريس المهارات اللغوية والعددية بما يسهم في تحسين الأداء والتحصيل.", "en": "Use technology and interactive digital applications in teaching language and numeracy skills to help improve performance and attainment."}, {"ar": "تشجيع المتعلمين على المشاركة في المسابقات الوطنية والدولية لتنمية التنافس الإيجابي وتعزيز مهارات القراءة والكتابة والرياضيات.", "en": "Encourage learners to take part in national and international competitions to foster positive competition and strengthen reading, writing and mathematics skills."}, {"ar": "تطوير قدرات المعلمين ومتابعة تنفيذ الخطط بطرق مبتكرة تضمن استدامة التحسين وجودة نواتج التعلم لدى جميع المتعلمين.", "en": "Develop teachers' capabilities and follow up plan implementation in innovative ways that ensure sustained improvement and quality learning outcomes for all learners."}], "2-1-1-7": [{"ar": "تطبيق استراتيجيات تعلم نشط ومتنوعة ومتمركزة حول الطالب (مثل: التعلم القائم على المشكلات، والمشروعات، والاستقصاء، والعصف الذهني) لتنمية مهارات التفكير والبحث والاستنتاج والتقويم لدى المتعلمين.", "en": "Apply varied, active, student-centered learning strategies (such as problem-based learning, projects, inquiry and brainstorming) to develop learners' thinking, research, inference and evaluation skills."}, {"ar": "تصميم أنشطة صفية ولاصفية محفزة للتفكير الإبداعي والنقدي، ترتبط بالمواقف الحياتية الواقعية وتتيح للمتعلمين فرصاً لتوليد أفكار وحلول مبتكرة.", "en": "Design classroom and extracurricular activities that stimulate creative and critical thinking, linked to real-life situations and giving learners opportunities to generate innovative ideas and solutions."}, {"ar": "دمج مهارات التفكير العليا في جميع المواد الدراسية من خلال أنشطة تحليل النصوص وتفسير النتائج واستخلاص المفاهيم وربطها بالتطبيقات العملية.", "en": "Integrate higher-order thinking skills into all subjects through activities such as analyzing texts, interpreting results, drawing out concepts and linking them to practical applications."}, {"ar": "تنفيذ مهام تعلم مفتوحة النهاية تتطلب من المتعلمين البحث والتقصي والمقارنة والتفسير، وتقديم مخرجات تعكس عمق التفكير والتحليل والابتكار.", "en": "Carry out open-ended learning tasks that require learners to research, investigate, compare and interpret, and to produce outputs that reflect depth of thinking, analysis and innovation."}, {"ar": "توظيف التقنية الرقمية والوسائط التفاعلية لتوسيع فرص التعلم والبحث والابتكار وتنمية مهارات التفكير العليا لدى جميع المتعلمين، بمن فيهم الموهوبون وذوو الإعاقة.", "en": "Use digital technology and interactive media to widen opportunities for learning, research and innovation and to develop higher-order thinking skills in all learners, including gifted learners and learners with disabilities."}, {"ar": "تهيئة بيئة تعلم محفزة للنقاش والحوار البناء، تدعم تبادل وجهات النظر وطرح الأسئلة وتقييم الأدلة للوصول إلى استنتاجات منطقية.", "en": "Create a learning environment that stimulates discussion and constructive dialogue, supporting the exchange of viewpoints, questioning and evaluating evidence in order to reach logical conclusions."}, {"ar": "تقديم أنشطة إثرائية متنوعة ومبتكرة تنمي مهارات التقويم والإبداع والبحث، مثل: التجارب، والمسابقات العلمية، والنوادي الفكرية، وحل المشكلات الواقعية.", "en": "Offer varied, innovative enrichment activities that develop evaluation, creativity and research skills, such as experiments, science competitions, intellectual clubs and real-world problem solving."}, {"ar": "متابعة تنفيذ الأنشطة وتنمية التفكير والبحث والابتكار بانتظام من خلال أدوات تقويم نوعية (ملاحظة، وملف إنجاز، ومهام أداء) لقياس مستوى الإبداع والتحليل والتقويم لدى المتعلمين.", "en": "Regularly follow up the implementation of activities and the development of thinking, research and innovation using qualitative assessment tools (observation, portfolio, performance tasks) to measure learners' level of creativity, analysis and evaluation."}], "2-1-1-8": [{"ar": "تنفيذ برامج تعليمية وأنشطة صفية ولاصفية تستهدف تنمية مهارات التحكم في العواطف وضبط الانفعالات والتفاعل الإيجابي مع الآخرين.", "en": "Implement educational programs and classroom and extracurricular activities that develop skills of controlling emotions, regulating reactions and interacting positively with others."}, {"ar": "تهيئة بيئة صفية آمنة وتعاونية تشجع العمل الجماعي والمناقشة والحوار الفعال، ويسودها الاحترام المتبادل بين المتعلمين.", "en": "Create a safe, cooperative classroom environment that encourages teamwork, discussion and effective dialogue, in which mutual respect prevails among learners."}, {"ar": "دمج مهارات التواصل العاطفي والاجتماعي في الممارسات التعليمية اليومية عبر مواقف تعلم تعزز التعبير عن المشاعر وإدارتها بوعي واتزان.", "en": "Integrate emotional and social communication skills into daily teaching practice through learning situations that promote expressing and managing feelings with awareness and balance."}, {"ar": "تفعيل أنشطة تعلم تفاعلية متنوعة، مثل المسرح التربوي والمناقشات الجماعية ولعب الأدوار والمحاكاة لتنمية التعاطف والتفاهم المتبادل.", "en": "Activate varied interactive learning activities, such as educational theater, group discussions, role play and simulation, to develop empathy and mutual understanding."}, {"ar": "تنفيذ برامج إرشادية وتوعوية تُعنى بتنمية الذكاء العاطفي لدى المتعلمين وتدريبهم على التعامل الإيجابي مع المواقف الانفعالية.", "en": "Implement guidance and awareness programs concerned with developing learners' emotional intelligence and training them to deal positively with emotional situations."}, {"ar": "تحفيز المتعلمين على تبادل الأفكار واحترام وجهات النظر، وتعزيز قيم التسامح وقبول التنوع والتعاون البناء في بيئة التعلم.", "en": "Motivate learners to exchange ideas and respect viewpoints, and reinforce the values of tolerance, acceptance of diversity and constructive cooperation in the learning environment."}, {"ar": "توظيف استراتيجيات تربوية فعالة لتنمية مهارات الضبط الانفعالي والتفاعل الإيجابي في المواقف الصفية.", "en": "Use effective educational strategies to develop emotional-regulation skills and positive interaction in classroom situations."}, {"ar": "متابعة أثر البرامج والأنشطة بطرق مبتكرة لقياس مدى تحسن مهارات التحكم في العواطف والتواصل الإيجابي بين المتعلمين.", "en": "Follow up the impact of programs and activities in innovative ways to measure improvement in emotional-control skills and positive communication among learners."}], "2-1-1-9": [{"ar": "تنويع أساليب وأنشطة التعلم لتشمل الألعاب التعليمية وتمثيل الأدوار والتجارب العملية والقصص والرسوم والأفلام، بما يثير فضول المتعلمين ويزيد من متعتهم بالتعلم.", "en": "Diversify learning methods and activities to include educational games, role play, hands-on experiments, stories, drawings and films, arousing learners' curiosity and increasing their enjoyment of learning."}, {"ar": "تطبيق أساليب تحفيزية إيجابية متنوعة (الإشادة والثناء، والمكافآت الرمزية، والاحتفاء بالمنجزات) لرفع دافعية المتعلمين وتشجيعهم على المبادرة والمشاركة.", "en": "Apply varied positive motivational methods (praise and commendation, symbolic rewards, celebrating achievements) to raise learners' motivation and encourage initiative and participation."}, {"ar": "تهيئة بيئة تعلم آمنة ومحفزة يسودها الاحترام المتبادل والتقدير والثقة، وتدعم الشعور بالراحة والرفاه النفسي والاجتماعي للمتعلمين.", "en": "Create a safe, stimulating learning environment marked by mutual respect, appreciation and trust, supporting learners' sense of comfort and psychological and social well-being."}, {"ar": "تصميم أنشطة تعلم تراعي الميول والرغبات الفردية وتكشف عن اهتمامات المتعلمين وتشجعهم على البحث والاكتشاف.", "en": "Design learning activities that take individual inclinations and wishes into account, reveal learners' interests and encourage them to research and discover."}, {"ar": "تطبيق استراتيجيات تعلم تفاعلية تعتمد على الحوار والمناقشة وطرح الأسئلة والاستقصاء لتنمية حب التعلم وحب الاستطلاع.", "en": "Apply interactive learning strategies based on dialogue, discussion, questioning and inquiry to develop a love of learning and curiosity."}, {"ar": "متابعة دافعية المتعلمين واهتماماتهم من خلال ملاحظات صفية واستطلاعات رأي تقيس التحسن في تفاعلهم وفضولهم للتعلم.", "en": "Follow up learners' motivation and interests through classroom observations and opinion surveys that measure improvement in their engagement and curiosity to learn."}, {"ar": "تمكين المتعلمين من التعبير عن آرائهم وأفكارهم بثقة، وتقدير مبادراتهم، وتشجيعهم على دعم زملائهم والتعاون في تنفيذ الأنشطة.", "en": "Empower learners to express their opinions and ideas confidently, appreciate their initiatives, and encourage them to support peers and cooperate in carrying out activities."}, {"ar": "توظيف التقنية والوسائط المتعددة في تصميم أنشطة ممتعة ومشوقة تعزز الفضول والاكتشاف وتربط التعلم بمتعة التجربة والبحث الذاتي.", "en": "Use technology and multimedia in designing enjoyable, engaging activities that foster curiosity and discovery and connect learning with the pleasure of experimentation and self-directed research."}], "2-2-1-1": [{"ar": "تطبيق أساليب تقويم متنوعة وفاعلة (تشخيصي/تكويني/ختامي) للكشف المبكر عن مستويات أداء المتعلمين وتصنيفهم (دون/ضمن/فوق).", "en": "Apply varied, effective assessment methods (diagnostic/formative/summative) to detect learners' performance levels early and classify them (below/within/above)."}, {"ar": "تنويع أدوات التقويم (ملف إنجاز، ومهام أداء، ومشاريع، واختبارات، وملاحظة، وتقويم إلكتروني) لضمان شمولية القياس وإظهار الفروق في مستويات الأداء.", "en": "Diversify assessment tools (portfolio, performance tasks, projects, tests, observation, electronic assessment) to ensure comprehensive measurement and reveal differences in performance levels."}, {"ar": "توظيف نتائج التقويم التشخيصي والتكويني لتحديد الفجوات التعليمية وتصنيف المتعلمين إلى فئات الأداء المناسبة.", "en": "Use diagnostic and formative assessment results to identify learning gaps and classify learners into the appropriate performance categories."}, {"ar": "إعداد خطة معالجة مرتبطة بالمستويات، بحيث تتضمن: إعادة تعلّم لفئة (دون المتوسط)، وتعزيز/تثبيت لفئة (ضمن المتوسط)، وإثراء/توسع لفئة (فوق المتوسط).", "en": "Prepare a remediation plan linked to the levels, including: re-learning for the below-average group, reinforcement/consolidation for the average group, and enrichment/extension for the above-average group."}, {"ar": "تشجيع المتعلمين على المشاركة الفاعلة في تقويم أدائهم (تقويم ذاتي/تقويم الأقران) لرفع الوعي بالمستوى وتعزيز المسؤولية عن التعلم.", "en": "Encourage learners to take an active part in assessing their own performance (self-/peer assessment) to raise awareness of their level and strengthen responsibility for learning."}, {"ar": "تفعيل التقويم الإلكتروني وأدوات التحليل الرقمية لرصد مستويات الأداء وإصدار تقارير تُظهر الفئات (دون/ضمن/فوق) واتجاهات التقدم.", "en": "Activate electronic assessment and digital analysis tools to track performance levels and issue reports showing the categories (below/within/above) and progress trends."}, {"ar": "تطوير أداء المعلمين في بناء أدوات تشخيص المستويات وتحليل النتائج عبر التدريب المستمر وتبادل الخبرات المهنية، لتحسين دقة الكشف عن المستويات.", "en": "Develop teachers' performance in building level-diagnosis tools and analyzing results through continuous training and exchange of professional expertise, to improve the accuracy of detecting levels."}, {"ar": "متابعة فاعلية التقويم وخطط المعالجة حسب الفئات بانتظام، وقياس أثر إعادة التعلم/التعزيز/الإثراء على انتقال المتعلمين بين المستويات والتحسين المستمر.", "en": "Regularly follow up the effectiveness of assessment and remediation plans by category, and measure the impact of re-learning/reinforcement/enrichment on learners' movement between levels and on continuous improvement."}], "2-2-1-2": [{"ar": "تطبيق أساليب تقويم متنوعة وفاعلة (تشخيصي/تكويني/ختامي) لقياس تحقق نواتج التعلم المستهدفة في المناهج.", "en": "Apply varied, effective assessment methods (diagnostic/formative/summative) to measure achievement of the targeted learning outcomes in the curricula."}, {"ar": "تنويع أدوات التقويم (مهام أداء، ومشاريع، واختبارات، وعروض، وملف إنجاز، وملاحظة، وتقويم إلكتروني)، وربط كل أداة بنواتج تعلم محددة.", "en": "Diversify assessment tools (performance tasks, projects, tests, presentations, portfolio, observation, electronic assessment) and link each tool to specific learning outcomes."}, {"ar": "إعداد مصفوفة مواءمة تقويمية تربط (نواتج التعلم المستهدفة ↔ أدوات التقويم ↔ معايير الأداء) لضمان صدق القياس.", "en": "Prepare an assessment alignment matrix linking (targeted learning outcomes ↔ assessment tools ↔ performance criteria) to ensure measurement validity."}, {"ar": "توظيف نتائج التقويم التكويني والختامي لتحديد نواتج التعلم غير المتحققة وأسبابها داخل الصف/المحتوى/استراتيجيات التدريس.", "en": "Use formative and summative assessment results to identify unachieved learning outcomes and their causes within the classroom, content and teaching strategies."}, {"ar": "تنفيذ معالجات تعليمية مرتبطة بالنواتج، تشمل إعادة تدريس/إعادة تعلم للنواتج غير المتحققة، وتعزيزاً للنواتج المتحققة جزئياً، وإثراءً للنواتج المتحققة بدرجة عالية.", "en": "Implement outcome-linked instructional remediation, including re-teaching/re-learning for unachieved outcomes, reinforcement for partially achieved outcomes, and enrichment for highly achieved outcomes."}, {"ar": "تفعيل أدوات التقويم الإلكتروني والتحليلات الرقمية لقياس تحقق النواتج وإصدار تقارير دورية توضح مستوى الإتقان لكل ناتج تعلم.", "en": "Activate electronic assessment tools and digital analytics to measure outcome achievement and issue periodic reports showing the mastery level for each learning outcome."}, {"ar": "رفع كفاءة المعلمين في تصميم أدوات تقويم معيارية وبناء سلالم تقدير، لتحسين جودة تقويم النواتج ودقة التغذية الراجعة.", "en": "Raise teachers' competence in designing standards-based assessment tools and building rating scales, to improve the quality of outcome assessment and the accuracy of feedback."}, {"ar": "مراجعة دورية لجودة التقويم ومدى مواءمته لنواتج التعلم، وتطوير الأدوات والمعايير بناءً على النتائج، لضمان التحسين المستمر لنواتج التعلم.", "en": "Periodically review the quality of assessment and its alignment with learning outcomes, and develop tools and criteria based on results, to ensure continuous improvement of learning outcomes."}], "2-2-1-3": [{"ar": "تحليل نتائج التقويم بطرق متنوعة لتحديد نقاط القوة وفرص التحسين في أداء المتعلمين، على مستوى المواد والمجالات التعليمية.", "en": "Analyze assessment results in varied ways to identify strengths and improvement opportunities in learners' performance, at the level of subjects and learning areas."}, {"ar": "تفسير نتائج التقويم بشكل منهجي وموضوعي من خلال لجان التحصيل الدراسي وفرق العمل، وربطها بمستويات الأداء الفعلية للمتعلمين.", "en": "Interpret assessment results systematically and objectively through academic achievement committees and work teams, and link them to learners' actual performance levels."}, {"ar": "توظيف نتائج التحليل في إعداد خطط علاجية وإثرائية تستهدف رفع مستوى التحصيل لدى المتعثرين، وتعزيز التفوق لدى الموهوبين والمتقدمين.", "en": "Use analysis results to prepare remedial and enrichment plans aimed at raising attainment among struggling learners and strengthening excellence among gifted and advanced learners."}, {"ar": "تنفيذ الخطط العلاجية والإثرائية بانتظام، باستخدام استراتيجيات تعليم متنوعة وأساليب دعم فردية وجماعية تناسب احتياجات المتعلمين.", "en": "Implement remedial and enrichment plans regularly, using varied teaching strategies and individual and group support methods suited to learners' needs."}, {"ar": "متابعة تنفيذ الخطط العلاجية والإثرائية بأساليب متعددة (زيارات صفية، وسجلات متابعة، وأدوات تقويم مستمر) لضمان تحقق الأهداف وتحسين نواتج التعلم.", "en": "Follow up the implementation of remedial and enrichment plans through multiple methods (classroom visits, follow-up records, continuous assessment tools) to ensure goals are achieved and learning outcomes improve."}, {"ar": "قياس الأثر والتقدم في نواتج التعلم عبر أدوات كمية ونوعية وتحليل نتائجها، لمراجعة الخطط وتطويرها بمرونة مستمرة.", "en": "Measure impact and progress in learning outcomes through quantitative and qualitative tools and analyze their results, to review and develop plans with continuous flexibility."}, {"ar": "ربط نتائج التقويم بخطط التطوير المهني للمعلمين لتحديد الاحتياجات التدريبية وتحسين الممارسات التعليمية بناءً على نتائج التحليل.", "en": "Link assessment results to teachers' professional development plans to identify training needs and improve teaching practices based on the analysis results."}, {"ar": "توظيف نتائج التحليل في اتخاذ القرارات التعليمية ومتابعة أثرها على تحسين نواتج التعلم، في ضوء مؤشرات الأداء والممارسات المهنية الفاعلة.", "en": "Use analysis results in making educational decisions and follow up their impact on improving learning outcomes, in light of performance indicators and effective professional practices."}], "2-2-1-4": [{"ar": "تقديم تغذية راجعة فورية ومنتظمة أثناء الموقف التعليمي وبعده، توضح للمتعلمين نقاط القوة وفرص التحسين في أدائهم بطرق إيجابية ومحفزة.", "en": "Provide immediate, regular feedback during and after the teaching situation that shows learners their strengths and opportunities for improvement in positive, motivating ways."}, {"ar": "تنويع أساليب التغذية الراجعة لتشمل التعليق الشفوي والكتابي والإلكتروني، وتقديم الملاحظات، والتشجيع، والتصحيح التفاعلي، بما يناسب طبيعة الموقف التعليمي.", "en": "Diversify feedback methods to include oral, written and electronic comments, observations, encouragement and interactive correction, as suits the nature of the teaching situation."}, {"ar": "ربط التغذية الراجعة بنتائج التقويم التشخيصي والتكويني لتوجيه المتعلمين نحو تحسين أدائهم وتنمية مهارات التفكير والتعلم الذاتي.", "en": "Link feedback to diagnostic and formative assessment results to guide learners toward improving their performance and developing thinking and self-learning skills."}, {"ar": "توظيف التغذية الراجعة لدعم التعلم المستمر من خلال مناقشات صفية بنّاءة وتقديم إرشادات محددة تساعد المتعلم على تحسين إنتاجه التعلمي خطوة بخطوة.", "en": "Use feedback to support continuous learning through constructive classroom discussions and specific guidance that helps learners improve their work step by step."}, {"ar": "مراعاة الفروق الفردية في تقديم التغذية الراجعة عبر أساليب متنوعة تراعي احتياجات المتعلمين وقدراتهم، وتمنحهم فرصاً لتصحيح أخطائهم ذاتياً.", "en": "Take individual differences into account when giving feedback, through varied methods that consider learners' needs and abilities and give them opportunities to correct their own mistakes."}, {"ar": "إشراك المتعلمين في عملية التغذية الراجعة من خلال التقويم الذاتي وتقويم الأقران، لتشجيع تحمل المسؤولية عن التعلم وتحفيز المبادرة.", "en": "Involve learners in the feedback process through self- and peer assessment, to encourage responsibility for learning and stimulate initiative."}, {"ar": "توظيف التقنية في تقديم التغذية الراجعة، مثل المنصات التعليمية والتطبيقات الرقمية التي توفر ملاحظات فورية وتدعم التواصل المستمر بين المعلم والمتعلم.", "en": "Use technology in delivering feedback, such as educational platforms and digital applications that provide instant comments and support continuous communication between teacher and learner."}, {"ar": "متابعة أثر التغذية الراجعة على أداء المتعلمين بانتظام وتحليل نتائجها لقياس مدى تحسن الأداء وتطوير أساليب الدعم والتقويم.", "en": "Regularly follow up the impact of feedback on learners' performance and analyze its results to measure performance improvement and develop support and assessment methods."}], "3-1-1-1": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-1-1-2": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-1-1-3": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-1-1-4": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-1-1-5": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-1-1-6": [{"ar": "تجويد الأداء في جميع مؤشرات مجال الإدارة المدرسية ومجال التعليم والتعلم، مع متابعة تقدم الأداء بشكل مستمر.", "en": "Improve performance across all indicators of the School Administration domain and the Teaching and Learning domain, with continuous monitoring of performance progress."}, {"ar": "تحليل نتائج الاختبارات الوطنية وتوظيفها لتحديد المهارات الأساسية التي تحتاج إلى تحسين، ووضع خطة تطوير مستهدفة لها.", "en": "Analyze national test results and use them to identify the core skills needing improvement, and set a targeted development plan for them."}, {"ar": "تخصيص برامج علاجية وإثرائية لجميع طلاب المدرسة وفق نتائجهم في الاختبارات، مع متابعة التحسن الفردي للطلاب.", "en": "Allocate remedial and enrichment programs for all students according to their test results, with follow-up of each student's individual improvement."}, {"ar": "تنويع استراتيجيات التدريس داخل الفصول بما يتناسب مع أنماط التعلم واحتياجات المتعلمين، والتركيز على مهارات التفكير العليا والفهم والتحليل والتطبيق.", "en": "Diversify teaching strategies in classrooms to suit learning styles and learners' needs, focusing on higher-order thinking skills, comprehension, analysis and application."}, {"ar": "تنفيذ أنشطة تعلم تطبيقية ومهارية في العلوم والرياضيات والقراءة تربط المعرفة بالممارسة وتنمّي مهارات التفكير العملي والعلمي.", "en": "Carry out applied, skills-based learning activities in science, mathematics and reading that link knowledge with practice and develop practical and scientific thinking skills."}, {"ar": "تفعيل أدوات التقويم المتنوعة داخل الحصص الدراسية (اختبارات قصيرة، وملاحظة أداء، وملفات إنجاز، ومهام أدائية) لتقويم مدى اكتساب الطلاب للمهارات المستهدفة.", "en": "Activate varied assessment tools within lessons (short quizzes, performance observation, portfolios, performance tasks) to evaluate how well students acquire the targeted skills."}, {"ar": "تقديم تغذية راجعة فورية للمتعلمين توضح نقاط القوة وفرص التحسين، وتساعدهم على تصحيح أخطائهم وتطوير أدائهم القرائي والعلمي والرياضي.", "en": "Give learners immediate feedback that shows strengths and opportunities for improvement and helps them correct their mistakes and develop their reading, science and mathematics performance."}, {"ar": "تنمية دافعية المتعلمين للتعلم والتفوق في الاختبارات الوطنية عبر بيئة صفية مشجعة، وبرامج تحفيزية ومسابقات علمية وقرائية منتظمة.", "en": "Develop learners' motivation to learn and excel in national tests through an encouraging classroom environment, motivational programs and regular science and reading competitions."}], "3-2-1-1": [{"ar": "تضمين القيم الوطنية والهوية الوطنية بصورة صريحة في الخطة التشغيلية للمدرسة وبرامجها وأنشطتها ومشروعاتها الطلابية، ومتابعة تنفيذ ما ورد فيها ميدانياً.", "en": "Explicitly include national values and identity in the school's operational plan, programs, activities and student projects, and follow up their implementation in the field."}, {"ar": "نشر الوعي بالقيم والهوية الوطنية لدى المتعلمين من خلال تنفيذ برامج ثقافية وتوعوية ومسابقات وإذاعات وحصص نشاط، وتنفيذ برامج وأنشطة صفية ولاصفية تعزز الانتماء والولاء للوطن، وتنظيم فعاليات وطنية في المناسبات الرسمية (اليوم الوطني، ويوم التأسيس، ويوم العلم).", "en": "Raise learners' awareness of national values and identity through educational and awareness programs, competitions, broadcasts and activity periods, classroom and extracurricular programs that strengthen belonging and loyalty to the homeland, and national events on official occasions (National Day, Founding Day, Flag Day)."}, {"ar": "دمج القيم والهوية الوطنية في الممارسات التعليمية اليومية من خلال تحفيز المعلمين على ربط المحتوى الدراسي بمواقف واقعية وقصص وقدوات وطنية، وتضمين ذلك في استراتيجيات التعلم التعاوني والأنشطة الصفية والواجبات والمشروعات الطلابية.", "en": "Integrate national values and identity into daily teaching practice by encouraging teachers to link course content to real situations, stories and national role models, and to include this in cooperative learning strategies, classroom activities, assignments and student projects."}, {"ar": "إبراز الرموز والهوية الوطنية في البيئة المدرسية (العلم، والشعار، والعبارات والقيم الوطنية، والأركان التعريفية، وصور القدوات الوطنية) وتوظيفها في أنشطة يومية مثل تحية العلم وفقرة «قيمة وطنية اليوم».", "en": "Display national symbols and identity in the school environment (the flag, the emblem, national phrases and values, information corners, pictures of national role models) and use them in daily activities such as the flag salute and a \"National Value of the Day\" segment."}, {"ar": "تعزيز السلوك الإيجابي المرتبط بالانتماء للوطن من خلال تفعيل مبادرات طلابية خدمية داخل المدرسة وخارجها، وتكريم الطلاب الذين يُظهرون سلوكاً يعكس الاعتزاز بالقيم الوطنية والمحافظة على الممتلكات والالتزام بالأنظمة والتعليمات.", "en": "Reinforce positive behavior linked to belonging to the homeland by activating student service initiatives inside and outside the school, and honoring students who show behavior reflecting pride in national values, care for property, and compliance with regulations and instructions."}, {"ar": "تفعيل الشراكة المجتمعية في تعزيز الهوية الوطنية عبر التعاون مع الجهات ذات العلاقة لتنظيم أنشطة وبرامج وطنية داخل المدرسة، وإشراك أولياء الأمور في برامج وحملات تسهم في ترسيخ القيم الوطنية لدى أبنائهم.", "en": "Activate community partnership in strengthening national identity by cooperating with relevant bodies to organize national activities and programs in the school, and involving parents in programs and campaigns that help instill national values in their children."}, {"ar": "تنفيذ زيارات إشرافية دورية (من قيادة المدرسة والفرق المدرسية ومقدمي الدعم) لرصد تطبيق القيم الوطنية في الصفوف والمشروعات والأنشطة والبيئة المدرسية، وتقديم تغذية راجعة فورية محفّزة على التطوير والتحسين.", "en": "Carry out periodic supervisory visits (by school leadership, school teams and support providers) to observe the application of national values in classrooms, projects, activities and the school environment, and give immediate feedback that encourages development and improvement."}, {"ar": "المتابعة والتقويم المستمر لمستوى تحقق المؤشر من خلال تحليل نتائج مؤشرات الأداء في مجال القيم والانتماء الوطني ضمن «تقارير الدعم والتحسين»، وإعداد تقارير دورية توضح جوانب القوة وفرص التحسين، وتضمين خطط تحسين مستمرة تعزز اعتزاز المتعلمين بالقيم والهوية الوطنية.", "en": "Continuously monitor and evaluate the level of achieving the indicator by analyzing performance-indicator results in the area of national values and belonging within the \"support and improvement reports\", preparing periodic reports showing strengths and improvement opportunities, and including continuous improvement plans that strengthen learners' pride in national values and identity."}], "3-2-1-2": [{"ar": "إدراج تنمية الاتجاهات الإيجابية نحو الذات ضمن الخطة التشغيلية وبرامج المدرسة، من خلال أهداف واضحة وأنشطة محددة.", "en": "Include the development of positive attitudes toward the self in the operational plan and school programs, through clear goals and specific activities."}, {"ar": "تنفيذ برامج إرشادية وتوعوية وأنشطة صفية ولاصفية تنمّي الثقة بالنفس ومهارات التعبير عن الرأي وتقدير الإنجاز الشخصي، ودعم المبادرات الطلابية داخل المدرسة.", "en": "Implement guidance and awareness programs and classroom and extracurricular activities that build self-confidence, skills of expressing opinions and appreciation of personal achievement, and support student initiatives within the school."}, {"ar": "تهيئة بيئة صفية ومدرسية آمنة ومحفزة عبر توجيه المعلمين لاستخدام أساليب تشجيعية ولغة داعمة، ومنع السخرية والتنمر، ومتابعة التزامهم بذلك.", "en": "Create a safe, stimulating classroom and school environment by directing teachers to use encouraging methods and supportive language, preventing mockery and bullying, and following up their compliance."}, {"ar": "تفعيل المجالس والبرامج القيادية الطلابية بتمكين المتعلمين من المشاركة في اتخاذ القرار وتنظيم الأنشطة وتحمل مسؤولية مهام محددة داخل المدرسة.", "en": "Activate student councils and leadership programs by enabling learners to take part in decision-making, organize activities and take responsibility for specific tasks within the school."}, {"ar": "تقديم الدعم النفسي والاجتماعي للمتعلمين من خلال تنفيذ برامج وأنشطة تعزز التوازن النفسي وتقدير الذات، ورصد الحالات التي تحتاج إلى دعم خاص، وإعداد خطط دعم فردية أو جماعية مناسبة لها بالتعاون مع الجهات المعنية داخل المدرسة وخارجها.", "en": "Provide psychological and social support to learners through programs and activities that strengthen psychological balance and self-esteem, identify cases needing special support, and prepare suitable individual or group support plans in cooperation with relevant parties inside and outside the school."}, {"ar": "تنظيم أندية وبرامج ومشروعات لاكتشاف مواهب المتعلمين وميولهم وتنميتها، مع إتاحة الفرص لعرض أعمالهم ومنتجاتهم أمام زملائهم وأولياء أمورهم.", "en": "Organize clubs, programs and projects to discover and develop learners' talents and interests, giving them opportunities to present their work and products to peers and parents."}, {"ar": "تنفيذ برامج للاحتفاء بإنجازات المتعلمين، وتكريم من يُظهر سلوكيات إيجابية تعكس الثقة بالنفس وتحمل المسؤولية، ونشر قصص نجاحهم في لوحات المدرسة ومنصاتها الرقمية.", "en": "Implement programs to celebrate learners' achievements, honor those who show positive behaviors reflecting self-confidence and responsibility, and publish their success stories on school boards and digital platforms."}, {"ar": "متابعة وتقويم أثر هذه الإجراءات من خلال الزيارات الصفية وأدوات الملاحظة والاستبانات، وتحليل نتائج مؤشرات الأداء المتعلقة بالجوانب الشخصية والاجتماعية، وتحديث خطط التحسين وفق ما تسفر عنه النتائج.", "en": "Follow up and evaluate the impact of these measures through classroom visits, observation tools and surveys, analyze performance-indicator results related to personal and social aspects, and update improvement plans according to the results."}], "3-2-1-3": [{"ar": "إدراج تعزيز الممارسات الصحية السليمة ضمن الخطة التشغيلية وبرامج المدرسة وأنشطتها، مع التركيز على التغذية السليمة والنظافة الشخصية والنشاط البدني والوقاية من الأمراض.", "en": "Include the promotion of sound health practices in the operational plan, school programs and activities, focusing on proper nutrition, personal hygiene, physical activity and disease prevention."}, {"ar": "تنفيذ برامج توعوية صحية دورية من خلال الإذاعة المدرسية والعروض التقديمية وحصص النشاط والنشرات، للتوعية بأهمية الغذاء المتوازن والنظافة الشخصية وشرب الماء والنوم الكافي، بالتعاون مع الجهات الصحية المختصة.", "en": "Implement periodic health awareness programs through the school broadcast, presentations, activity periods and bulletins, raising awareness of the importance of a balanced diet, personal hygiene, drinking water and adequate sleep, in cooperation with the competent health authorities."}, {"ar": "تفعيل الأنشطة والحملات الصحية المدرسية بتنظيم حملات صحية داخل المدرسة، وتفعيل اليوم العالمي للصحة ويوم الغذاء الصحي عبر أنشطة توعوية وتفاعلية يشارك فيها المتعلمون.", "en": "Activate school health activities and campaigns by organizing health campaigns in the school and marking World Health Day and Healthy Food Day through awareness and interactive activities in which learners participate."}, {"ar": "تنظيم أنشطة رياضية منتظمة من خلال حصص تربية بدنية فعالة، وبرامج حركية في الطابور الصباحي، ومنافسات رياضية ودوريات تشجع المتعلمين على ممارسة النشاط البدني اليومي.", "en": "Organize regular sports activities through effective physical education lessons, movement programs in the morning assembly, and sports competitions and leagues that encourage learners to be physically active every day."}, {"ar": "متابعة تطبيق العادات الصحية اليومية داخل الصف والمدرسة مثل غسل اليدين والعناية بالنظافة الشخصية والمظهر والجلسة الصحية والمحافظة على نظافة الفصول والمرافق، مع وضع لوحات إرشادية ورسائل تذكير مناسبة.", "en": "Follow up the application of daily health habits in the classroom and school, such as handwashing, personal hygiene and appearance, healthy posture, and keeping classrooms and facilities clean, with guidance boards and suitable reminder messages."}, {"ar": "تهيئة بيئة مدرسية داعمة للصحة عبر متابعة نظافة المبنى والمرافق، ومراقبة المقصف المدرسي للتأكد من تقديم خيارات غذائية صحية والحد من المأكولات والمشروبات الضارة، وتوفير مياه شرب آمنة للمتعلمين.", "en": "Create a health-supportive school environment by monitoring the cleanliness of the building and facilities, supervising the school canteen to ensure healthy food options and limit harmful foods and drinks, and providing safe drinking water for learners."}, {"ar": "تفعيل الشراكة مع الأسرة والمراكز الصحية من خلال عقد لقاءات توعوية، ودعوة مختصين صحيين لتقديم برامج وفحوصات دورية، وتزويد أولياء الأمور برسائل وإرشادات تعزز الممارسات الصحية في المنزل والمدرسة.", "en": "Activate partnership with families and health centers by holding awareness meetings, inviting health specialists to provide programs and periodic check-ups, and giving parents messages and guidance that reinforce healthy practices at home and at school."}, {"ar": "متابعة التزام المتعلمين بالممارسات الصحية وتقويمها باستخدام الزيارات الصفية وأدوات الملاحظة المنظمة والاستبانات وتحليل مؤشرات الأداء في الجوانب الصحية، وإدراج النتائج في تقارير الدعم والتحسين وخطط التطوير المستمرة.", "en": "Follow up and evaluate learners' adherence to health practices using classroom visits, structured observation tools, surveys and analysis of performance indicators in health aspects, and include the results in support and improvement reports and continuous development plans."}], "3-2-1-4": [{"ar": "تشكيل فريق العمل التطوعي في المدرسة، وتمكين المتعلمين ومنسوبي المدرسة من المبادرات التطوعية عبر إشراكهم في اختيار الأفكار وتصميم المبادرات وتنفيذها، وتحديد مهام أعضاء الفريق ومسؤولياتهم.", "en": "Form a volunteer work team in the school and enable learners and school staff to lead volunteer initiatives by involving them in choosing ideas, designing and implementing initiatives, and defining team members' tasks and responsibilities."}, {"ar": "حث المتعلمين ومنسوبي المدرسة على التسجيل في منصة العمل التطوعي، وتقديم الدعم لمن يواجه صعوبة في التسجيل، ومتابعة استكمال بياناتهم، والتأكد من مشاركتهم في فرص تطوعية متنوعة (عامة، ومهارية، واحترافية) تتناسب مع ميولهم وقدراتهم.", "en": "Urge learners and school staff to register on the volunteer work platform, support those who have difficulty registering, follow up on completion of their data, and ensure they take part in varied volunteer opportunities (general, skills-based, professional) matching their interests and abilities."}, {"ar": "تعزيز ثقافة التطوع والمسؤولية المجتمعية من خلال تنفيذ برامج تعريفية وتوعوية بمفهوم العمل التطوعي وأثره في خدمة المجتمع والوطن، واستثمار الإذاعة المدرسية والحصص واللقاءات في ترسيخ قيم العطاء والانتماء.", "en": "Promote a culture of volunteering and social responsibility through introductory and awareness programs on the concept of volunteer work and its impact on serving society and the nation, using the school broadcast, lessons and meetings to instill values of giving and belonging."}, {"ar": "تضمين المشاركات المجتمعية والأعمال التطوعية في الخطة التشغيلية وبرامج المدرسة وربطها بالأنشطة الصفية واللاصفية، لضمان استمراريتها وعدم اقتصارها على مناسبات محددة، وذلك وفق الأنظمة والتعليمات المنظمة.", "en": "Include community participation and volunteer work in the operational plan and school programs and link them to classroom and extracurricular activities, to ensure continuity rather than limiting them to specific occasions, in accordance with the governing regulations and instructions."}, {"ar": "تصميم فرص ومبادرات تطوعية وتنظيمها لمنسوبي المدرسة داخلها وخارجها، بمستويات متنوعة (عامة، ومهارية، واحترافية)، وفق الأنظمة والتعليمات المنظمة للعمل التطوعي.", "en": "Design and organize volunteer opportunities and initiatives for school staff inside and outside the school, at varied levels (general, skills-based, professional), in accordance with the regulations governing volunteer work."}, {"ar": "بناء شراكات مجتمعية فاعلة بالتعاون مع الجمعيات الخيرية والمراكز التطوعية والبلديات والجهات الصحية وأولياء الأمور، لتنفيذ برامج ميدانية مشتركة تدعم مشاركة المتعلمين في خدمة المجتمع المحلي، وفق الأنظمة والتعليمات المنظمة.", "en": "Build effective community partnerships with charities, volunteer centers, municipalities, health authorities and parents to carry out joint field programs that support learners' participation in serving the local community, in accordance with the governing regulations."}, {"ar": "تحفيز منسوبي المدرسة والمتعلمين المتميزين في الأنشطة المجتمعية والأعمال التطوعية بمنحهم شهادات شكر وتكريم، وإبراز إنجازاتهم عبر المنصات المدرسية والإعلامية، لتعزيز روح المبادرة لدى بقية المتعلمين.", "en": "Motivate outstanding school staff and learners in community activities and volunteer work by awarding certificates of appreciation and honors and highlighting their achievements on school and media platforms, to strengthen the spirit of initiative among other learners."}, {"ar": "متابعة مشاركات منسوبي المدرسة والمتعلمين في الأعمال التطوعية وتوثيقها في سجلات أو منصات معتمدة، وتحليل المؤشرات ذات العلاقة، وإعداد تقارير تتضمن ملاحظات وتحسينات وتوصيات، لتوسيع نطاق المشاركة المجتمعية في المدرسة.", "en": "Follow up and document school staff's and learners' participation in volunteer work in approved records or platforms, analyze related indicators, and prepare reports with observations, improvements and recommendations, to broaden community participation in the school."}], "3-2-1-5": [{"ar": "تجويد الأداء في جميع مؤشرات معيار قيادة العملية التعليمية.", "en": "Improve performance across all indicators of the Leading the Educational Process criterion."}, {"ar": "تعزيز الوعي بالسلوك والانضباط من خلال تنفيذ برامج توعوية منظمة حول أهمية الانضباط المدرسي والالتزام بقيم السلوك الإيجابي، وتوضيح لائحة قواعد السلوك والمواظبة للمتعلمين وأولياء الأمور.", "en": "Raise awareness of behavior and discipline through organized awareness programs on the importance of school discipline and commitment to positive behavior values, and by clarifying the code of conduct and attendance for learners and parents."}, {"ar": "تضمين الالتزام بقواعد السلوك والانضباط والمواظبة في الخطة التشغيلية وبرامج المدرسة وأنشطتها، ومتابعة تنفيذها من قبل جميع المعلمين ومنسوبي المدرسة.", "en": "Include commitment to the rules of conduct, discipline and attendance in the operational plan and school programs and activities, and have all teachers and school staff follow up their implementation."}, {"ar": "تفعيل المتابعة اليومية للحضور والانصراف والسلوك بالتنسيق مع وكلاء المدرسة والمعلمين، لرصد حالات الغياب والتأخر والمخالفات السلوكية ومعالجتها بالتواصل مع أولياء الأمور، وفق الأنظمة والتعليمات المنظمة.", "en": "Activate daily follow-up of arrival, departure and behavior in coordination with school deputies and teachers, to track absences, lateness and behavioral violations and address them by communicating with parents, in accordance with the governing regulations."}, {"ar": "تعزيز السلوك الإيجابي والانضباط المدرسي من خلال برامج تحفيزية متنوعة وتكريم المتعلمين الملتزمين بقواعد السلوك في الطابور الصباحي والفصول والمنصات المدرسية.", "en": "Reinforce positive behavior and school discipline through varied motivational programs and honoring learners who adhere to the rules of conduct in the morning assembly, classrooms and school platforms."}, {"ar": "تطبيق إجراءات واضحة وعادلة لمعالجة مخالفات السلوك والمواظبة، وفق لائحة قواعد السلوك والمواظبة والأنظمة والتعليمات المنظمة، مع تفعيل الجلسات الإرشادية للمتعلمين غير الملتزمين.", "en": "Apply clear, fair procedures to address violations of conduct and attendance rules, in accordance with the code of conduct and attendance and the governing regulations, with counseling sessions for non-compliant learners."}, {"ar": "تهيئة بيئة مدرسية وصفية منظمة وآمنة تعزز الانضباط من خلال تنظيم الاصطفاف، وضبط حركة المتعلمين داخل المدرسة، والمحافظة على نظافة المرافق، ووضوح التعليمات السلوكية في جميع أرجاء المدرسة.", "en": "Create an orderly, safe school and classroom environment that fosters discipline by organizing assembly lines, controlling learners' movement within the school, keeping facilities clean, and making behavioral instructions clear throughout the school."}, {"ar": "متابعة التزام المتعلمين بقواعد السلوك والانضباط وتقويمه من خلال سجلات السلوك والمواظبة والتقارير الدورية وتحليل المؤشرات، للاستفادة منها في تطوير الإجراءات الوقائية والعلاجية وتعزيز استمرارية الالتزام.", "en": "Follow up and evaluate learners' adherence to the rules of conduct and discipline through behavior and attendance records, periodic reports and indicator analysis, to improve preventive and remedial procedures and sustain compliance."}], "3-2-1-6": [{"ar": "تضمين برامج ومهارات البحث والتعلم الذاتي للمتعلمين ضمن الخطة التشغيلية للمدرسة وخطط المواد الدراسية والأنشطة الصفية واللاصفية، وفق الأنظمة والتعليمات المنظمة.", "en": "Include research and self-learning programs and skills for learners in the school's operational plan, subject plans and classroom and extracurricular activities, in accordance with the governing regulations."}, {"ar": "تنمية مهارات البحث والاستقصاء لدى المتعلمين من خلال ورش ودورات تطبيقية حول أساليب البحث العلمي المبسط وجمع المعلومات وتنظيمها وتوظيفها.", "en": "Develop learners' research and inquiry skills through applied workshops and courses on simplified scientific research methods and on gathering, organizing and using information."}, {"ar": "توظيف استراتيجيات تدريس نشطة (التعلم القائم على المشروعات، والاستقصاء، وحل المشكلات، والتعلم التعاوني) بما يعزز دافعية المتعلمين للبحث والتعلم الذاتي.", "en": "Use active teaching strategies (project-based learning, inquiry, problem solving, cooperative learning) that strengthen learners' motivation for research and self-learning."}, {"ar": "تكليف المتعلمين بمهام ومشروعات وبحوث فردية وجماعية متدرجة تتطلب الرجوع إلى مصادر تعلم متنوعة، مع تقديم الإرشاد والمتابعة خلال مراحل التنفيذ.", "en": "Assign learners graded individual and group tasks, projects and research that require consulting varied learning resources, with guidance and follow-up throughout the stages of implementation."}, {"ar": "تدريب المتعلمين على استخدام مصادر التعلم الرقمية الآمنة ومنصات التعليم الإلكتروني ومحركات البحث، وتنمية مهارات التحقق من موثوقية المعلومات وتوثيقها.", "en": "Train learners to use safe digital learning resources, e-learning platforms and search engines, and develop skills in verifying the reliability of information and documenting it."}, {"ar": "تنفيذ مبادرات وأنشطة بحثية ومسابقات علمية تعزز مهارات التفكير الناقد وحل المشكلات والإبداع، وتدعم مسؤولية المتعلم عن تعلمه الذاتي.", "en": "Carry out research initiatives and activities and science competitions that strengthen critical thinking, problem solving and creativity and support the learner's responsibility for their own self-learning."}, {"ar": "تحفيز المتعلمين المتميزين في البحث والتعلم الذاتي من خلال عرض نماذج أعمالهم وتكريمهم في الفعاليات المدرسية والمنصات الرقمية.", "en": "Motivate learners who excel in research and self-learning by showcasing samples of their work and honoring them at school events and on digital platforms."}, {"ar": "متابعة تنامي مهارات البحث والتعلم الذاتي وتقويمه لدى المتعلمين باستخدام أدوات متنوعة (ملفات الإنجاز، وعروض المشروعات، والاستبانات، والملاحظات الصفية) والاستفادة من النتائج في تحسين الخطط والإجراءات.", "en": "Follow up and evaluate the growth of learners' research and self-learning skills using varied tools (portfolios, project presentations, surveys, classroom observations) and use the results to improve plans and procedures."}], "3-2-1-7": [{"ar": "تضمين برامج الاعتزاز بالثقافة الوطنية واحترام التنوع الثقافي ضمن الخطة التشغيلية للمدرسة وبرامجها وأنشطتها الصفية واللاصفية، وفق الأنظمة والتعليمات المنظمة.", "en": "Include programs on pride in national culture and respect for cultural diversity in the school's operational plan, programs and classroom and extracurricular activities, in accordance with the governing regulations."}, {"ar": "تعزيز الهوية والثقافة الوطنية لدى المتعلمين من خلال برامج تعريفية بتاريخ الوطن وتراثه ورموزه، وتفعيل المناسبات الوطنية والثقافية وربطها بالقيم والسلوكيات الإيجابية في الحياة اليومية.", "en": "Strengthen national identity and culture among learners through programs introducing the nation's history, heritage and symbols, and by activating national and cultural occasions and linking them to positive values and behaviors in daily life."}, {"ar": "ترسيخ قيم الاحترام المتبادل والتسامح وقبول التنوع الثقافي عبر برامج توعوية وحوارات صفية ومنهجية وأنشطة تعاونية تعالج أي سلوكيات تنمر أو إقصاء أو إساءة قائمة على الخلفية الثقافية.", "en": "Instill values of mutual respect, tolerance and acceptance of cultural diversity through awareness programs, classroom and curricular dialogues and cooperative activities that address any bullying, exclusion or abuse based on cultural background."}, {"ar": "تنفيذ أنشطة طلابية وفعاليات متنوعة تبرز التنوع الثقافي لمناطق المملكة، وتشجع المتعلمين على تقديم مشاركات فنية وثقافية تعكس اعتزازهم بثقافتهم واحترامهم لثقافات الآخرين.", "en": "Carry out varied student activities and events that highlight the cultural diversity of the Kingdom's regions and encourage learners to give artistic and cultural contributions reflecting their pride in their own culture and respect for others' cultures."}, {"ar": "دمج القيم الثقافية والوطنية وقيم احترام التنوع في الممارسات التعليمية داخل الفصول من خلال توجيه المعلمين لتضمينها في الأمثلة والنصوص والأنشطة الصفية واللاصفية.", "en": "Integrate cultural and national values and respect for diversity into classroom teaching practices by directing teachers to include them in examples, texts and classroom and extracurricular activities."}, {"ar": "تفعيل الشراكة المجتمعية بالتعاون مع الجهات الثقافية والمراكز المجتمعية والأسر لتنفيذ برامج وفعاليات تعرّف المتعلمين بالتراث الوطني والتنوع الثقافي في المجتمع، وفق الأنظمة والتعليمات المنظمة.", "en": "Activate community partnership with cultural bodies, community centers and families to carry out programs and events that introduce learners to national heritage and cultural diversity in society, in accordance with the governing regulations."}, {"ar": "تحفيز المتعلمين الذين يظهرون سلوكاً يعكس الاعتزاز بالثقافة الوطنية واحترام التنوع من خلال تكريمهم وإبراز مشاركاتهم في المنصات المدرسية والإعلامية، لتشجيع بقية المتعلمين على الاقتداء بهم.", "en": "Motivate learners who show behavior reflecting pride in national culture and respect for diversity by honoring them and highlighting their contributions on school and media platforms, to encourage other learners to follow their example."}, {"ar": "متابعة اتجاهات المتعلمين وتقويمها نحو ثقافتهم واحترامهم للتنوع الثقافي باستخدام الاستبانات والملاحظات الصفية، وتحليل نتائج الأداء المرتبطة بالقيم الثقافية، والاستفادة من النتائج في تحسين البرامج والأنشطة ذات الصلة.", "en": "Follow up and evaluate learners' attitudes toward their culture and their respect for cultural diversity using surveys and classroom observations, analyze performance results linked to cultural values, and use the results to improve related programs and activities."}]};
